/**
 * TERRA BELLUM — strategic overlays on the global map.
 *
 * Ping shockwaves and glyphs, pinned marks, objective beacons, guild territory
 * borders, sector boundary light curtains, locked-sector fog and "last seen"
 * intel ghosts — all instanced into eight draw calls.
 *
 * Text is rasterised into ONE dynamically packed canvas atlas and drawn through
 * a single instanced billboard batch, so labels cost nothing extra and there is
 * no webfont dependency (system monospace / symbol stacks only).
 */
import * as THREE from 'three';
import type {
  GameState,
  GuildId,
  HexId,
  IntelSnapshot,
  PingKind,
  PlayerId,
  Terrain,
} from '../../game/types';
import type { ViewState } from '../../game/store';
import { GUILD, MAP_VIEW, PALETTE, PING_META } from '../../config';
import { AXIAL_DIRECTIONS, axialToWorld, hexId as makeHexId, parseHexId } from '../../game/hex';
import {
  InstancedBatch,
  armyChevronGeometry,
  beaconRingGeometry,
  billboardQuadGeometry,
  diamondMarkerGeometry,
  hexPlateGeometry,
  lightColumnGeometry,
} from '../core/geometry';
import {
  GLSL_NOISE,
  makeAtlasBillboardMaterial,
  makeDecalMaterial,
  makeEnergyFieldMaterial,
  makeGlowSpriteMaterial,
  makeHoloLineMaterial,
  makeTokenMaterial,
  registerMaterial,
  type FxMaterial,
} from '../core/materials';
import { SimClock, type Quality } from '../core/stage';
import { hexTopY } from './hexField';
import { fmtAgo } from '../../ui/dom';

const HEX_R = MAP_VIEW.hexRadius;
const APOTHEM = HEX_R * 0.8660254;
const SIDE_HALF = HEX_R * 0.5;
const BORDER_INSET = 0.955;
const CURTAIN_HEIGHT = 3.4;

const V = new THREE.Vector3();
const M4 = new THREE.Matrix4();
const UP_AXIS = new THREE.Vector3(0, 1, 0);
const QUAT = new THREE.Quaternion();
const SCALE = new THREE.Vector3(1, 1, 1);
const COL = new THREE.Color();
const COL2 = new THREE.Color();

// ─────────────────────────────────────────────────────────────────────────────
// Label atlas
// ─────────────────────────────────────────────────────────────────────────────

export interface AtlasRect {
  u0: number;
  v0: number;
  du: number;
  dv: number;
  /** width / height of the rasterised chip. */
  aspect: number;
}

export interface LabelStyle {
  color?: string;
  chip?: string;
  border?: string;
  /** Use the symbol font stack instead of the monospace stack. */
  glyph?: boolean;
  scale?: number;
}

const MONO_STACK = 'ui-monospace, "SF Mono", "Roboto Mono", Menlo, Consolas, monospace';
const SYMBOL_STACK = '"Segoe UI Symbol", "Apple Symbols", system-ui, sans-serif';

/**
 * Dynamically packed canvas atlas. Labels are rasterised once and cached by
 * text + style; when the sheet fills up it is wiped and repacked on demand.
 */
export class LabelAtlas {
  readonly texture: THREE.CanvasTexture;

  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D | null;
  private readonly size: number;
  private readonly px: number;
  private readonly cache = new Map<string, AtlasRect>();
  private cx = 2;
  private cy = 2;
  private rowH = 0;

  constructor(dpr = 1) {
    const scale = Math.min(2, Math.max(1, dpr));
    this.size = scale >= 1.75 ? 2048 : 1024;
    this.px = Math.round(26 * scale);
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.size;
    this.canvas.height = this.size;
    this.ctx = this.canvas.getContext('2d');
    this.texture = new THREE.CanvasTexture(this.canvas);
    this.texture.colorSpace = THREE.SRGBColorSpace;
    this.texture.minFilter = THREE.LinearFilter;
    this.texture.magFilter = THREE.LinearFilter;
    this.texture.generateMipmaps = false;
    this.texture.needsUpdate = true;
  }

  /** Rasterises (or returns the cached rect for) a label chip. */
  get(text: string, style: LabelStyle = {}): AtlasRect | null {
    const key = `${text}|${style.color ?? ''}|${style.chip ?? ''}|${style.border ?? ''}|${style.glyph ? 'g' : 't'}|${style.scale ?? 1}`;
    const hit = this.cache.get(key);
    if (hit) return hit;
    const ctx = this.ctx;
    if (!ctx) return null;

    const fontPx = Math.round(this.px * (style.scale ?? 1));
    const font = `${style.glyph ? '500' : '700'} ${fontPx}px ${style.glyph ? SYMBOL_STACK : MONO_STACK}`;
    ctx.font = font;
    if ('letterSpacing' in ctx) {
      try {
        (ctx as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = style.glyph
          ? '0px'
          : `${Math.max(1, fontPx * 0.06)}px`;
      } catch {
        /* unsupported — harmless */
      }
    }
    const metrics = ctx.measureText(text);
    const padX = Math.round(fontPx * (style.glyph ? 0.3 : 0.42));
    const padY = Math.round(fontPx * 0.3);
    const w = Math.ceil(metrics.width) + padX * 2;
    const h = fontPx + padY * 2;

    if (this.cx + w + 2 > this.size) {
      this.cx = 2;
      this.cy += this.rowH + 2;
      this.rowH = 0;
    }
    if (this.cy + h + 2 > this.size) {
      // sheet is full — wipe and repack from scratch
      ctx.clearRect(0, 0, this.size, this.size);
      this.cache.clear();
      this.cx = 2;
      this.cy = 2;
      this.rowH = 0;
    }

    const x = this.cx;
    const y = this.cy;

    ctx.save();
    ctx.clearRect(x, y, w, h);
    const chip = style.chip ?? 'rgba(4,10,20,0.62)';
    if (chip !== 'none') {
      roundRect(ctx, x + 1, y + 1, w - 2, h - 2, Math.round(h * 0.24));
      ctx.fillStyle = chip;
      ctx.fill();
    }
    const border = style.border;
    if (border) {
      roundRect(ctx, x + 1.5, y + 1.5, w - 3, h - 3, Math.round(h * 0.24));
      ctx.lineWidth = Math.max(1.5, fontPx * 0.07);
      ctx.strokeStyle = border;
      ctx.stroke();
      // corner bracket accents
      ctx.beginPath();
      const b = Math.round(h * 0.28);
      ctx.moveTo(x + 2, y + b);
      ctx.lineTo(x + 2, y + 2);
      ctx.lineTo(x + 2 + b, y + 2);
      ctx.moveTo(x + w - 2 - b, y + h - 2);
      ctx.lineTo(x + w - 2, y + h - 2);
      ctx.lineTo(x + w - 2, y + h - 2 - b);
      ctx.lineWidth = Math.max(1.5, fontPx * 0.1);
      ctx.stroke();
    }

    ctx.font = font;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = style.color ?? '#eaf6ff';
    ctx.shadowColor = style.color ?? '#4de3ff';
    ctx.shadowBlur = Math.round(fontPx * 0.45);
    ctx.fillText(text, x + w / 2, y + h / 2 + 1);
    ctx.restore();

    this.cx += w + 2;
    this.rowH = Math.max(this.rowH, h);
    this.texture.needsUpdate = true;

    const rect: AtlasRect = {
      u0: x / this.size,
      v0: 1 - (y + h) / this.size,
      du: w / this.size,
      dv: h / this.size,
      aspect: w / h,
    };
    this.cache.set(key, rect);
    return rect;
  }

  dispose(): void {
    this.cache.clear();
    this.texture.dispose();
  }
}

function roundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

// ─────────────────────────────────────────────────────────────────────────────
// Locked-sector fog material (instanced hex plates)
// ─────────────────────────────────────────────────────────────────────────────

function makeLockedFogMaterial(): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColor: { value: new THREE.Color(0x3f7fb5).multiplyScalar(0.6) },
      uOpacity: { value: 0.55 },
    },
    vertexShader: /* glsl */ `
      attribute vec3 iAux;
      varying vec2 vUvC;
      varying vec3 vWorld;
      varying vec3 vAux;
      void main() {
        mat4 im = mat4(1.0);
        #ifdef USE_INSTANCING
          im = instanceMatrix;
        #endif
        vUvC = uv;
        vAux = iAux;
        vec4 world = modelMatrix * im * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform float uTime;
      uniform vec3 uColor;
      uniform float uOpacity;
      varying vec2 vUvC;
      varying vec3 vWorld;
      varying vec3 vAux;
      ${GLSL_NOISE}
      void main() {
        vec2 p = vUvC * 2.0 - 1.0;
        float hd = tbHexDist(p);
        if (hd > 1.0) discard;

        // drifting fog bank
        float fog = tbFbm2(vWorld.xz * 0.42 + vec2(uTime * 0.035, -uTime * 0.022));
        float body = smoothstep(0.25, 0.85, fog);

        // dissolving grid
        vec2 g = abs(fract(vWorld.xz * 2.1 + 0.5) - 0.5);
        float grid = 1.0 - smoothstep(0.0, 0.055, min(g.x, g.y));
        float diss = smoothstep(0.30, 0.78, fog + 0.2 * sin(uTime * 0.6 + vAux.y * 30.0));

        // rim seal
        float rim = smoothstep(0.86, 1.0, hd);

        vec3 col = uColor * (0.35 + body * 0.65);
        col += uColor * grid * (0.7 - 0.5 * diss) * 1.6;
        col += uColor * rim * 1.9;

        float a = (0.16 + body * 0.24 + grid * 0.32 * (1.0 - diss) + rim * 0.5) * uOpacity * vAux.x;
        if (a <= 0.003) discard;
        gl_FragColor = vec4(col, a);
      }
    `,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  mat.name = 'tb.lockedFog';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Display-list records (reused every frame — no per-frame allocation)
// ─────────────────────────────────────────────────────────────────────────────

interface LabelItem {
  x: number;
  y: number;
  z: number;
  rect: AtlasRect;
  height: number;
  r: number;
  g: number;
  b: number;
  alpha: number;
  bob: number;
}

interface GlowItem {
  x: number;
  y: number;
  z: number;
  size: number;
  r: number;
  g: number;
  b: number;
  alpha: number;
  phase: number;
}

interface MarkerItem {
  x: number;
  y: number;
  z: number;
  r: number;
  g: number;
  b: number;
  scale: number;
  seed: number;
}

interface ShockItem {
  x: number;
  y: number;
  z: number;
  r: number;
  g: number;
  b: number;
  /** Seconds (relative to `this.elapsed`) at spawn, or a phase for looping waves. */
  born: number;
  life: number;
  maxScale: number;
}

interface ColumnItem {
  x: number;
  y: number;
  z: number;
  r: number;
  g: number;
  b: number;
  intensity: number;
}

interface GhostItem {
  x: number;
  y: number;
  z: number;
  r: number;
  g: number;
  b: number;
  seed: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// MapOverlays
// ─────────────────────────────────────────────────────────────────────────────

export class MapOverlays {
  readonly group = new THREE.Group();
  readonly atlas: LabelAtlas;
  readonly clock = new SimClock();

  private readonly labelMat: FxMaterial;
  private readonly glowMat: FxMaterial;
  private readonly shockMat: FxMaterial;
  private readonly markMat: FxMaterial;
  private readonly ghostMat: FxMaterial;
  private readonly columnMat: FxMaterial;
  private readonly borderMat: FxMaterial;
  private readonly curtainMat: FxMaterial;
  private readonly fogMat: FxMaterial;

  private readonly labels: InstancedBatch;
  private readonly glows: InstancedBatch;
  private readonly shocks: InstancedBatch;
  private readonly marks: InstancedBatch;
  private readonly ghosts: InstancedBatch;
  private readonly columns: InstancedBatch;
  private readonly lockedFog: InstancedBatch;

  private borderMesh: THREE.Mesh | null = null;
  private curtainMesh: THREE.Mesh | null = null;
  private borderSig = 0;
  private curtainSig = 0;

  private labelItems: LabelItem[] = [];
  private glowItems: GlowItem[] = [];
  private markItems: MarkerItem[] = [];
  private ghostItems: GhostItem[] = [];
  private columnItems: ColumnItem[] = [];
  /** Looping shockwaves owned by live pings — rebuilt on every sync. */
  private pingWaves: ShockItem[] = [];
  /** One-shot pulses fired by MapScene; removed when they expire. */
  private transientWaves: ShockItem[] = [];

  private elapsed = 0;
  private readonly quality: Quality;

  constructor(quality: Quality = 'high', dpr = 1) {
    this.quality = quality;
    this.group.name = 'overlays';
    this.atlas = new LabelAtlas(dpr);

    this.labelMat = makeAtlasBillboardMaterial(this.atlas.texture, false);
    this.glowMat = makeGlowSpriteMaterial(0xffffff, 2.5);
    this.shockMat = makeDecalMaterial(0xffffff, { mode: 'ring', additive: true });
    this.markMat = makeTokenMaterial(0xffffff, { emissive: 1.6 });
    this.ghostMat = makeTokenMaterial(0xffffff, { ghost: true, emissive: 1.2 });
    this.columnMat = makeEnergyFieldMaterial(0xffffff);
    this.columnMat.uniforms.uOpacity.value = 0.45;
    this.borderMat = makeHoloLineMaterial(0xffffff, { opacity: 0.6 });
    this.curtainMat = makeEnergyFieldMaterial(0xffffff);
    this.curtainMat.uniforms.uOpacity.value = 0.7;
    this.fogMat = makeLockedFogMaterial();

    const colorAux = [
      { name: 'iColor', size: 3, fill: [1, 1, 1] },
      { name: 'iAux', size: 3, fill: [1, 0, 0] },
    ];

    this.lockedFog = new InstancedBatch(
      this.group,
      hexPlateGeometry(HEX_R * 0.985),
      this.fogMat,
      256,
      colorAux,
    );
    this.lockedFog.setRenderOrder(3);

    this.shocks = new InstancedBatch(
      this.group,
      beaconRingGeometry(1, 0.1, quality === 'low' ? 36 : 72),
      this.shockMat,
      48,
      colorAux,
    );
    this.shocks.setRenderOrder(12);

    this.columns = new InstancedBatch(
      this.group,
      lightColumnGeometry(0.3, 7, quality === 'low' ? 8 : 14),
      this.columnMat,
      32,
      [
        { name: 'aIntensity', size: 1, fill: [1] },
        { name: 'aTint', size: 3, fill: [1, 1, 1] },
      ],
    );
    this.columns.setRenderOrder(13);

    this.marks = new InstancedBatch(
      this.group,
      diamondMarkerGeometry(0.17),
      this.markMat,
      GUILD.maxMarks + 8,
      colorAux,
    );
    this.marks.setRenderOrder(14);

    this.ghosts = new InstancedBatch(
      this.group,
      armyChevronGeometry(0.4),
      this.ghostMat,
      96,
      colorAux,
    );
    this.ghosts.setRenderOrder(15);

    this.glows = new InstancedBatch(
      this.group,
      billboardQuadGeometry(1),
      this.glowMat,
      128,
      colorAux,
    );
    this.glows.setRenderOrder(16);

    this.labels = new InstancedBatch(this.group, billboardQuadGeometry(1), this.labelMat, 160, [
      { name: 'iRect', size: 4, fill: [0, 0, 1, 1] },
      { name: 'iAux', size: 3, fill: [1, 1, 1] },
      { name: 'iColor', size: 3, fill: [1, 1, 1] },
    ]);
    this.labels.setRenderOrder(24);
  }

  // ── state sync ────────────────────────────────────────────────────────────

  sync(state: GameState, view: ViewState): void {
    this.clock.sync(state.now);
    const now = state.now;
    const meId: PlayerId = state.meId;
    const myGuild: GuildId | undefined = state.players[meId]?.guildId;

    this.labelItems.length = 0;
    this.glowItems.length = 0;
    this.markItems.length = 0;
    this.ghostItems.length = 0;
    this.columnItems.length = 0;
    this.pingWaves.length = 0;

    if (view.layers.pings) this.collectPings(state, now, myGuild);
    if (view.layers.marks) this.collectMarks(state, myGuild);
    if (view.layers.objectives) this.collectObjectives(state, myGuild);
    if (view.layers.intel) this.collectIntel(state, now, myGuild);

    this.collectSectorLabels(state, now);
    this.rebuildBorders(state);
    this.rebuildCurtains(state, now);
    this.rebuildLockedFog(state);
  }

  // ── pings ─────────────────────────────────────────────────────────────────

  private collectPings(state: GameState, now: number, myGuild: GuildId | undefined): void {
    for (const ping of state.pings) {
      if (myGuild !== undefined && ping.guildId !== myGuild) continue;
      if (ping.expiresAt <= now) continue;
      const hex = state.world.hexes[ping.hexId];
      if (!hex) continue;
      this.hexTop(ping.hexId, hex.terrain, V);

      const meta = PING_META[ping.kind as PingKind];
      COL.set(meta.color);
      const life = Math.max(1, ping.expiresAt - ping.at);
      const remain = Math.max(0, Math.min(1, (ping.expiresAt - now) / life));
      const alpha = 0.35 + 0.65 * Math.min(1, remain * 3);

      this.glowItems.push({
        x: V.x,
        y: V.y + 0.5,
        z: V.z,
        size: 2.2,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        alpha: alpha * 0.55,
        phase: hashUnit(ping.id),
      });

      this.pingWaves.push({
        x: V.x,
        y: V.y + 0.06,
        z: V.z,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        born: hashUnit(ping.id) * 1.5,
        life: 1.5,
        maxScale: HEX_R * 2.6,
      });

      const glyph = this.atlas.get(meta.glyph, { glyph: true, color: meta.color, chip: 'none' });
      if (glyph) {
        this.labelItems.push({
          x: V.x,
          y: V.y + 1.15,
          z: V.z,
          rect: glyph,
          height: 0.72,
          r: COL.r,
          g: COL.g,
          b: COL.b,
          alpha,
          bob: 0.09,
        });
      }
      const tag = this.atlas.get(meta.label, {
        color: meta.color,
        border: meta.color,
        chip: 'rgba(3,8,16,0.72)',
        scale: 0.62,
      });
      if (tag) {
        this.labelItems.push({
          x: V.x,
          y: V.y + 1.75,
          z: V.z,
          rect: tag,
          height: 0.3,
          r: COL.r,
          g: COL.g,
          b: COL.b,
          alpha: alpha * 0.95,
          bob: 0.05,
        });
      }
    }
  }

  // ── marks ─────────────────────────────────────────────────────────────────

  private collectMarks(state: GameState, myGuild: GuildId | undefined): void {
    for (const mark of state.marks) {
      if (myGuild !== undefined && mark.guildId !== myGuild) continue;
      const hex = state.world.hexes[mark.hexId];
      if (!hex) continue;
      this.hexTop(mark.hexId, hex.terrain, V);
      COL.setHex(PALETTE.violet);

      this.markItems.push({
        x: V.x,
        y: V.y + 0.1,
        z: V.z,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        scale: 1,
        seed: hashUnit(mark.id),
      });
      this.glowItems.push({
        x: V.x,
        y: V.y + 0.42,
        z: V.z,
        size: 0.95,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        alpha: 0.5,
        phase: hashUnit(mark.id),
      });

      const rect = this.atlas.get(mark.label.slice(0, 22).toUpperCase(), {
        color: '#c8b6ff',
        border: 'rgba(157,123,255,0.85)',
        chip: 'rgba(6,10,24,0.78)',
        scale: 0.72,
      });
      if (rect) {
        this.labelItems.push({
          x: V.x,
          y: V.y + 0.98,
          z: V.z,
          rect,
          height: 0.34,
          r: 1,
          g: 1,
          b: 1,
          alpha: 0.95,
          bob: 0.03,
        });
      }
    }
  }

  // ── objectives ────────────────────────────────────────────────────────────

  private collectObjectives(state: GameState, myGuild: GuildId | undefined): void {
    for (const obj of state.objectives) {
      if (obj.done) continue;
      if (myGuild !== undefined && obj.guildId !== myGuild) continue;
      const tint = obj.grand ? PALETTE.gold : PALETTE.teal;
      COL.setHex(tint);
      const css = obj.grand ? '#ffd15c' : '#3dffcf';
      let first = true;
      for (const id of obj.hexIds) {
        const hex = state.world.hexes[id];
        if (!hex) continue;
        this.hexTop(id, hex.terrain, V);
        this.columnItems.push({
          x: V.x,
          y: V.y,
          z: V.z,
          r: COL.r,
          g: COL.g,
          b: COL.b,
          intensity: obj.grand ? 1 : 0.7,
        });
        this.glowItems.push({
          x: V.x,
          y: V.y + 0.18,
          z: V.z,
          size: 2.8,
          r: COL.r,
          g: COL.g,
          b: COL.b,
          alpha: obj.grand ? 0.5 : 0.34,
          phase: hashUnit(obj.id),
        });
        if (first) {
          first = false;
          const rect = this.atlas.get(obj.title.slice(0, 26).toUpperCase(), {
            color: css,
            border: css,
            chip: 'rgba(3,8,16,0.8)',
            scale: 0.78,
          });
          if (rect) {
            this.labelItems.push({
              x: V.x,
              y: V.y + 2.5,
              z: V.z,
              rect,
              height: 0.42,
              r: 1,
              g: 1,
              b: 1,
              alpha: 1,
              bob: 0.06,
            });
          }
        }
      }
    }
  }

  // ── intel ghosts ──────────────────────────────────────────────────────────

  private collectIntel(state: GameState, now: number, myGuild: GuildId | undefined): void {
    if (myGuild === undefined) return;
    const snapshots = state.intel[myGuild];
    if (!snapshots) return;

    const occupied = new Set<HexId>();
    for (const army of Object.values(state.armies)) occupied.add(army.hexId);

    let drawn = 0;
    for (const key of Object.keys(snapshots)) {
      if (drawn >= 90) break;
      const snap: IntelSnapshot = snapshots[key];
      if (!snap || !snap.army) continue;
      if (occupied.has(snap.hexId)) continue;
      const hex = state.world.hexes[snap.hexId];
      if (!hex) continue;
      this.hexTop(snap.hexId, hex.terrain, V);

      if (snap.guildId && state.guilds[snap.guildId]) COL.setHex(state.guilds[snap.guildId].color);
      else COL.setHex(PALETTE.crimson);

      this.ghostItems.push({
        x: V.x,
        y: V.y + 0.36,
        z: V.z,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        seed: hashUnit(snap.hexId),
      });

      const tag = `${snap.army.guildTag || '???'} ×${snap.army.unitCount} · ${fmtAgo(snap.at, now)}`;
      const rect = this.atlas.get(tag, {
        color: '#9fd7ff',
        chip: 'rgba(3,8,16,0.62)',
        border: 'rgba(77,227,255,0.35)',
        scale: 0.58,
      });
      if (rect) {
        this.labelItems.push({
          x: V.x,
          y: V.y + 0.92,
          z: V.z,
          rect,
          height: 0.26,
          r: 1,
          g: 1,
          b: 1,
          alpha: 0.7,
          bob: 0,
        });
      }
      drawn++;
    }
  }

  // ── sector countdown labels ───────────────────────────────────────────────

  private collectSectorLabels(state: GameState, now: number): void {
    for (const sector of Object.values(state.world.sectors)) {
      if (sector.state === 'active') continue;
      const centerId = makeHexId(sector.center.q, sector.center.r);
      const hex = state.world.hexes[centerId];
      const terrain: Terrain = hex ? hex.terrain : 'plains';
      this.hexTop(centerId, terrain, V);

      const closing = sector.state === 'closing';
      const at = closing ? sector.closesAt : sector.opensAt;
      const css = closing ? '#ff8a3d' : sector.state === 'unlocking' ? '#3dffcf' : '#6f86a8';
      const remain = at !== undefined ? Math.max(0, at - now) : 0;
      const verb = closing ? 'COLLAPSE' : sector.state === 'unlocking' ? 'OPENS' : 'LOCKED';
      const text =
        at !== undefined && remain > 0
          ? `${sector.designation} · ${verb} ${countdown(remain)}`
          : `${sector.designation} · ${verb}`;

      const rect = this.atlas.get(text, {
        color: css,
        border: css,
        chip: 'rgba(2,6,12,0.85)',
        scale: 0.7,
      });
      if (rect) {
        this.labelItems.push({
          x: V.x,
          y: V.y + 3.1,
          z: V.z,
          rect,
          height: 0.44,
          r: 1,
          g: 1,
          b: 1,
          alpha: 0.95,
          bob: 0.05,
        });
      }
    }
  }

  // ── territory borders ─────────────────────────────────────────────────────

  private rebuildBorders(state: GameState): void {
    // ownership fingerprint (FNV-1a over hexId + region key)
    let sig = 2166136261;
    const regionOf = (hid: HexId): string => {
      const hex = state.world.hexes[hid];
      if (!hex || !hex.ownerId) return '';
      const player = state.players[hex.ownerId];
      return player?.guildId ? `g${player.guildId}` : `p${hex.ownerId}`;
    };
    const owned: HexId[] = [];
    for (const id of Object.keys(state.world.hexes)) {
      const region = regionOf(id);
      if (!region) continue;
      owned.push(id);
      const s = id + region;
      for (let i = 0; i < s.length; i++) {
        sig ^= s.charCodeAt(i);
        sig = Math.imul(sig, 16777619);
      }
    }
    sig = (sig >>> 0) ^ owned.length;
    if (sig === this.borderSig) return;
    this.borderSig = sig;

    this.disposeBorders();
    if (owned.length === 0) return;

    const edges: number[] = [];
    const colors: number[] = [];
    for (const id of owned) {
      const region = regionOf(id);
      const a = parseHexId(id);
      const w = axialToWorld(a, HEX_R);
      const hex = state.world.hexes[id];
      const y = hexTopY(hex.terrain) + 0.05;
      const guildId = state.players[hex.ownerId ?? '']?.guildId;
      if (guildId && state.guilds[guildId]) COL2.setHex(state.guilds[guildId].color);
      else COL2.setHex(PALETTE.edge);

      for (const dir of AXIAL_DIRECTIONS) {
        const nid = makeHexId(a.q + dir.q, a.r + dir.r);
        if (regionOf(nid) === region) continue;
        const dw = axialToWorld(dir, HEX_R);
        const dl = Math.hypot(dw.x, dw.z) || 1;
        const dx = dw.x / dl;
        const dz = dw.z / dl;
        const mx = w.x + dx * APOTHEM * BORDER_INSET;
        const mz = w.z + dz * APOTHEM * BORDER_INSET;
        const px = -dz * SIDE_HALF * BORDER_INSET;
        const pz = dx * SIDE_HALF * BORDER_INSET;
        edges.push(mx + px, y, mz + pz, mx - px, y, mz - pz);
        colors.push(COL2.r, COL2.g, COL2.b);
      }
    }

    const segs = colors.length / 3;
    if (segs === 0) return;
    const geo = buildEdgeRibbons(edges, colors, 0.11);
    const mesh = new THREE.Mesh(geo, this.borderMat);
    mesh.frustumCulled = false;
    mesh.renderOrder = 6;
    this.group.add(mesh);
    this.borderMesh = mesh;
  }

  // ── sector boundary curtains ──────────────────────────────────────────────

  private rebuildCurtains(state: GameState, now: number): void {
    let sig = 2166136261;
    const flagged: string[] = [];
    for (const sector of Object.values(state.world.sectors)) {
      if (sector.state === 'active') continue;
      flagged.push(sector.id);
      for (let i = 0; i < sector.id.length; i++) {
        sig ^= sector.id.charCodeAt(i);
        sig = Math.imul(sig, 16777619);
      }
      sig ^= sector.state.charCodeAt(0);
      sig = Math.imul(sig, 16777619);
    }
    sig = (sig >>> 0) ^ flagged.length;

    if (sig !== this.curtainSig) {
      this.curtainSig = sig;
      this.disposeCurtains();
      if (flagged.length > 0) this.buildCurtainMesh(state, flagged);
    }

    // countdown-driven intensity, refreshed every sync
    const mesh = this.curtainMesh;
    if (!mesh) return;
    const attr = mesh.geometry.getAttribute('aIntensity');
    const sectorOfVertex = mesh.geometry.userData.sectorOfVertex as string[] | undefined;
    if (!attr || !sectorOfVertex) return;
    const arr = attr.array as Float32Array;
    for (let i = 0; i < arr.length; i++) {
      const sector = state.world.sectors[sectorOfVertex[i]];
      arr[i] = sector ? curtainIntensity(sector.state, sector.closesAt, sector.opensAt, now) : 0;
    }
    attr.needsUpdate = true;
  }

  private buildCurtainMesh(state: GameState, sectorIds: string[]): void {
    const pos: number[] = [];
    const uvs: number[] = [];
    const intensity: number[] = [];
    const tints: number[] = [];
    const sectorOfVertex: string[] = [];
    const index: number[] = [];
    let base = 0;

    for (const sid of sectorIds) {
      const sector = state.world.sectors[sid];
      if (!sector) continue;
      COL2.setHex(
        sector.state === 'closing'
          ? PALETTE.ember
          : sector.state === 'unlocking'
            ? PALETTE.teal
            : PALETTE.cyanDeep,
      );
      const members = new Set(sector.hexIds);
      for (const id of sector.hexIds) {
        const hex = state.world.hexes[id];
        if (!hex) continue;
        const a = parseHexId(id);
        const w = axialToWorld(a, HEX_R);
        const y = hexTopY(hex.terrain);
        for (const dir of AXIAL_DIRECTIONS) {
          const nid = makeHexId(a.q + dir.q, a.r + dir.r);
          if (members.has(nid)) continue;
          const dw = axialToWorld(dir, HEX_R);
          const dl = Math.hypot(dw.x, dw.z) || 1;
          const dx = dw.x / dl;
          const dz = dw.z / dl;
          const mx = w.x + dx * APOTHEM;
          const mz = w.z + dz * APOTHEM;
          const px = -dz * SIDE_HALF;
          const pz = dx * SIDE_HALF;
          const ax = mx + px;
          const az = mz + pz;
          const bx = mx - px;
          const bz = mz - pz;
          const top = y + CURTAIN_HEIGHT;
          pos.push(ax, y, az, bx, y, bz, bx, top, bz, ax, top, az);
          uvs.push(0, 0, 1, 0, 1, 1, 0, 1);
          for (let k = 0; k < 4; k++) {
            intensity.push(1);
            tints.push(COL2.r, COL2.g, COL2.b);
            sectorOfVertex.push(sid);
          }
          index.push(base, base + 1, base + 2, base, base + 2, base + 3);
          base += 4;
        }
      }
    }
    if (base === 0) return;

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    const iAttr = new THREE.Float32BufferAttribute(intensity, 1);
    iAttr.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('aIntensity', iAttr);
    geo.setAttribute('aTint', new THREE.Float32BufferAttribute(tints, 3));
    geo.setAttribute(
      'normal',
      new THREE.Float32BufferAttribute(new Float32Array(base * 3).fill(0), 3),
    );
    geo.setIndex(index);
    geo.computeBoundingSphere();
    geo.userData.sectorOfVertex = sectorOfVertex;

    const mesh = new THREE.Mesh(geo, this.curtainMat);
    mesh.frustumCulled = false;
    mesh.renderOrder = 11;
    this.group.add(mesh);
    this.curtainMesh = mesh;
  }

  // ── locked sector fog plates ──────────────────────────────────────────────

  private rebuildLockedFog(state: GameState): void {
    const ids: HexId[] = [];
    for (const sector of Object.values(state.world.sectors)) {
      if (sector.state !== 'locked' && sector.state !== 'unlocking') continue;
      for (const id of sector.hexIds) ids.push(id);
    }
    this.lockedFog.ensure(Math.max(1, ids.length));
    this.lockedFog.begin();
    for (const id of ids) {
      const hex = state.world.hexes[id];
      if (!hex) continue;
      this.hexTop(id, hex.terrain, V);
      V.y += 0.07;
      M4.compose(V, QUAT.identity(), SCALE.set(1, 1, 1));
      const i = this.lockedFog.add(M4);
      if (i < 0) break;
      const sectorState = state.world.sectors[hex.sectorId]?.state;
      this.lockedFog.set(i, 'iColor', 1, 1, 1);
      this.lockedFog.set(i, 'iAux', sectorState === 'unlocking' ? 0.55 : 1, hashUnit(id), 0);
    }
    this.lockedFog.end();
  }

  // ── one-shot pulse (pings, captures, battles) ─────────────────────────────

  /** Fires a one-shot expanding shockwave at a world position. */
  pulse(worldPos: THREE.Vector3, color: number, scale = HEX_R * 3.2, life = 1.1): void {
    COL.setHex(color);
    if (this.transientWaves.length > 24) this.transientWaves.shift();
    this.transientWaves.push({
      x: worldPos.x,
      y: worldPos.y + 0.07,
      z: worldPos.z,
      r: COL.r,
      g: COL.g,
      b: COL.b,
      born: this.elapsed,
      life,
      maxScale: scale,
    });
  }

  // ── per-frame ─────────────────────────────────────────────────────────────

  update(dt: number): void {
    this.clock.advance(dt);
    this.elapsed += dt;
    const t = this.elapsed;

    // labels
    this.labels.ensure(this.labelItems.length + 2);
    this.labels.begin();
    for (const item of this.labelItems) {
      const bob = item.bob > 0 ? Math.sin(t * 1.6 + item.x * 0.4) * item.bob : 0;
      V.set(item.x, item.y + bob, item.z);
      M4.compose(V, QUAT.identity(), SCALE.set(1, 1, 1));
      const i = this.labels.add(M4);
      if (i < 0) break;
      this.labels.set(i, 'iRect', item.rect.u0, item.rect.v0, item.rect.du, item.rect.dv);
      this.labels.set(i, 'iAux', item.height * item.rect.aspect, item.height, item.alpha);
      this.labels.set(i, 'iColor', item.r, item.g, item.b);
    }
    this.labels.end();

    // glows
    this.glows.ensure(this.glowItems.length + 2);
    this.glows.begin();
    for (const item of this.glowItems) {
      V.set(item.x, item.y, item.z);
      M4.compose(V, QUAT.identity(), SCALE.set(1, 1, 1));
      const i = this.glows.add(M4);
      if (i < 0) break;
      this.glows.set(i, 'iColor', item.r, item.g, item.b);
      this.glows.set(i, 'iAux', item.size, item.alpha, item.phase);
    }
    this.glows.end();

    // marks
    this.marks.ensure(this.markItems.length + 2);
    this.marks.begin();
    for (const item of this.markItems) {
      const bob = Math.sin(t * 2.1 + item.seed * 14) * 0.06;
      V.set(item.x, item.y + bob, item.z);
      QUAT.setFromAxisAngle(UP_AXIS, t * 0.7 + item.seed * 6.28);
      M4.compose(V, QUAT, SCALE.set(item.scale, item.scale, item.scale));
      const i = this.marks.add(M4);
      if (i < 0) break;
      this.marks.set(i, 'iColor', item.r, item.g, item.b);
      this.marks.set(i, 'iAux', 1, 0, 0.8);
    }
    this.marks.end();
    QUAT.identity();

    // intel ghosts
    this.ghosts.ensure(this.ghostItems.length + 2);
    this.ghosts.begin();
    for (const item of this.ghostItems) {
      const flicker = 0.45 + 0.25 * Math.sin(t * 5.4 + item.seed * 30);
      V.set(item.x, item.y + Math.sin(t * 1.3 + item.seed * 9) * 0.04, item.z);
      QUAT.setFromAxisAngle(UP_AXIS, item.seed * 6.28 + t * 0.15);
      M4.compose(V, QUAT, SCALE.set(1, 1, 1));
      const i = this.ghosts.add(M4);
      if (i < 0) break;
      this.ghosts.set(i, 'iColor', item.r, item.g, item.b);
      this.ghosts.set(i, 'iAux', flicker, 0, 0.4);
    }
    this.ghosts.end();
    QUAT.identity();

    // objective light columns
    this.columns.ensure(this.columnItems.length + 2);
    this.columns.begin();
    for (const item of this.columnItems) {
      V.set(item.x, item.y, item.z);
      M4.compose(V, QUAT.identity(), SCALE.set(1, 1, 1));
      const i = this.columns.add(M4);
      if (i < 0) break;
      this.columns.set(i, 'aIntensity', item.intensity * (0.75 + 0.25 * Math.sin(t * 1.9)));
      this.columns.set(i, 'aTint', item.r, item.g, item.b);
    }
    this.columns.end();

    // shockwaves — looping ping waves plus one-shot pulses
    this.shocks.ensure(this.pingWaves.length + this.transientWaves.length + 2);
    this.shocks.begin();
    for (const s of this.pingWaves) {
      this.drawShock(s, (t + s.born) % s.life);
    }
    for (let k = this.transientWaves.length - 1; k >= 0; k--) {
      const s = this.transientWaves[k];
      const age = t - s.born;
      if (age > s.life) {
        this.transientWaves.splice(k, 1);
        continue;
      }
      this.drawShock(s, age);
    }
    this.shocks.end();
  }

  private drawShock(s: ShockItem, age: number): void {
    const p = Math.min(1, Math.max(0, age / s.life));
    const eased = 1 - Math.pow(1 - p, 2.2);
    const radius = 0.25 + eased * s.maxScale;
    V.set(s.x, s.y, s.z);
    M4.compose(V, QUAT.identity(), SCALE.set(radius, 1, radius));
    const i = this.shocks.add(M4);
    if (i < 0) return;
    this.shocks.set(i, 'iColor', s.r, s.g, s.b);
    this.shocks.set(i, 'iAux', (1 - p) * (1 - p) * 1.15, s.born, 0);
  }

  // ── helpers ───────────────────────────────────────────────────────────────

  private hexTop(id: HexId, terrain: Terrain, out: THREE.Vector3): THREE.Vector3 {
    const a = parseHexId(id);
    const w = axialToWorld(a, HEX_R);
    return out.set(w.x, hexTopY(terrain), w.z);
  }

  private disposeBorders(): void {
    if (!this.borderMesh) return;
    this.group.remove(this.borderMesh);
    this.borderMesh.geometry.dispose();
    this.borderMesh = null;
  }

  private disposeCurtains(): void {
    if (!this.curtainMesh) return;
    this.group.remove(this.curtainMesh);
    this.curtainMesh.geometry.dispose();
    this.curtainMesh = null;
  }

  dispose(): void {
    this.labels.dispose();
    this.glows.dispose();
    this.shocks.dispose();
    this.marks.dispose();
    this.ghosts.dispose();
    this.columns.dispose();
    this.lockedFog.dispose();
    this.disposeBorders();
    this.disposeCurtains();
    this.labelMat.dispose();
    this.glowMat.dispose();
    this.shockMat.dispose();
    this.markMat.dispose();
    this.ghostMat.dispose();
    this.columnMat.dispose();
    this.borderMat.dispose();
    this.curtainMat.dispose();
    this.fogMat.dispose();
    this.atlas.dispose();
    this.group.removeFromParent();
    this.group.clear();
    this.labelItems.length = 0;
    this.glowItems.length = 0;
    this.markItems.length = 0;
    this.ghostItems.length = 0;
    this.columnItems.length = 0;
    this.pingWaves.length = 0;
    this.transientWaves.length = 0;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// free functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Turns a flat list of world-space edge endpoints into one merged ribbon mesh
 * geometry (position / normal / uv / aDist / aColor) for the holo line shader.
 */
function buildEdgeRibbons(
  endpoints: number[],
  colors: number[],
  width: number,
): THREE.BufferGeometry {
  const segments = endpoints.length / 6;
  const pos = new Float32Array(segments * 4 * 3);
  const nrm = new Float32Array(segments * 4 * 3);
  const uvs = new Float32Array(segments * 4 * 2);
  const dst = new Float32Array(segments * 4);
  const col = new Float32Array(segments * 4 * 3);
  const index = new Uint32Array(segments * 6);
  const half = width * 0.5;

  for (let s = 0; s < segments; s++) {
    const o = s * 6;
    const ax = endpoints[o];
    const ay = endpoints[o + 1];
    const az = endpoints[o + 2];
    const bx = endpoints[o + 3];
    const by = endpoints[o + 4];
    const bz = endpoints[o + 5];
    let dx = bx - ax;
    let dz = bz - az;
    const len = Math.hypot(dx, dz) || 1;
    dx /= len;
    dz /= len;
    const px = -dz * half;
    const pz = dx * half;

    const r = colors[s * 3];
    const g = colors[s * 3 + 1];
    const b = colors[s * 3 + 2];

    const v = s * 4;
    const set = (i: number, x: number, y: number, z: number, u: number, vv: number, d: number) => {
      pos[i * 3] = x;
      pos[i * 3 + 1] = y;
      pos[i * 3 + 2] = z;
      nrm[i * 3 + 1] = 1;
      uvs[i * 2] = u;
      uvs[i * 2 + 1] = vv;
      dst[i] = d;
      col[i * 3] = r;
      col[i * 3 + 1] = g;
      col[i * 3 + 2] = b;
    };
    set(v + 0, ax + px, ay, az + pz, 0, 0, 0);
    set(v + 1, ax - px, ay, az - pz, 0, 1, 0);
    set(v + 2, bx + px, by, bz + pz, 1, 0, len);
    set(v + 3, bx - px, by, bz - pz, 1, 1, len);

    const ii = s * 6;
    index[ii] = v;
    index[ii + 1] = v + 1;
    index[ii + 2] = v + 3;
    index[ii + 3] = v;
    index[ii + 4] = v + 3;
    index[ii + 5] = v + 2;
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  geo.setAttribute('aDist', new THREE.BufferAttribute(dst, 1));
  geo.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
  geo.setIndex(new THREE.BufferAttribute(index, 1));
  geo.computeBoundingSphere();
  return geo;
}

function curtainIntensity(
  state: string,
  closesAt: number | undefined,
  opensAt: number | undefined,
  now: number,
): number {
  if (state === 'closing') {
    if (closesAt === undefined) return 0.4;
    const remain = Math.max(0, closesAt - now);
    // ramps from 0.2 a week out to 0.9 in the final hour
    const hours = remain / 3_600_000;
    return 0.2 + 0.7 * Math.min(1, 1 / (1 + hours * 0.06));
  }
  if (state === 'unlocking') return 0.35;
  return 0.18;
}

function countdown(ms: number): string {
  const s = Math.floor(ms / 1000);
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  if (d > 0) return `${d}D ${h}H`;
  if (h > 0) return `${h}H ${m}M`;
  return `${m}M`;
}

function hashUnit(key: string): number {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 10000) / 10000;
}
