/**
 * TERRA BELLUM — deep-space backdrop.
 *
 * Three layers, three draw calls:
 *   1. an inverted sphere carrying a layered-fbm nebula and a galactic band
 *   2. MAP_VIEW.starCount instanced points, each twinkling on its own phase
 *   3. MAP_VIEW.dustCount drifting motes that parallax against the field
 *
 * The nebula and the starfield ride with the camera so they read as infinitely
 * far away; the dust stays in world space so it parallaxes.
 */
import * as THREE from 'three';
import { MAP_VIEW } from '../../config/visual';
import { GLSL_NOISE, registerMaterial, type FxMaterial } from './materials';
import type { Quality } from './postfx';

const NEBULA_VERT = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = normalize(position);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const NEBULA_FRAG = /* glsl */ `
precision highp float;
uniform float uTime;
uniform vec3 uDeep;
uniform vec3 uIndigo;
uniform vec3 uTeal;
uniform vec3 uBand;
uniform float uIntensity;
varying vec3 vDir;

${GLSL_NOISE}

void main() {
  vec3 d = normalize(vDir);
  float t = uTime * 0.006;

  // layered nebula clouds
  float n1 = tbFbm3(d * 1.55 + vec3(t, t * 0.6, -t * 0.4));
  float n2 = tbFbm3(d * 3.4 + vec3(-t * 0.8, t * 0.5, t * 0.9) + 21.7);
  float n3 = tbNoise3(d * 7.1 + 4.3);

  float clouds = smoothstep(0.36, 0.86, n1 * 0.72 + n2 * 0.42);
  float wisps = smoothstep(0.52, 0.92, n2 * 0.85 + n3 * 0.25);

  vec3 col = uDeep;
  col = mix(col, uIndigo, clouds * 0.95);
  col = mix(col, uTeal, wisps * 0.42 * smoothstep(-0.35, 0.75, d.y));

  // faint galactic band across the sky
  float bandCoord = dot(d, normalize(vec3(0.62, 0.34, -0.71)));
  float band = exp(-bandCoord * bandCoord * 26.0);
  float bandNoise = tbFbm3(d * 5.5 + 11.0);
  col += uBand * band * (0.30 + 0.70 * bandNoise) * 0.85;

  // horizon lift so the map floor never meets a hard edge
  col += uDeep * 1.4 * (1.0 - smoothstep(-0.55, 0.25, d.y));

  gl_FragColor = vec4(col * uIntensity, 1.0);
}
`;

const STAR_VERT = /* glsl */ `
attribute float aSize;
attribute float aPhase;
attribute vec3 aTint;
uniform float uTime;
uniform float uPixelRatio;
varying float vTwinkle;
varying vec3 vTint;
void main() {
  vTint = aTint;
  float tw = 0.55 + 0.45 * sin(uTime * (0.6 + aPhase * 2.4) + aPhase * 62.8);
  vTwinkle = 0.35 + 0.65 * tw * tw;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * uPixelRatio * (0.65 + 0.55 * vTwinkle);
  gl_Position = projectionMatrix * mv;
}
`;

const STAR_FRAG = /* glsl */ `
precision highp float;
uniform float uOpacity;
varying float vTwinkle;
varying vec3 vTint;
void main() {
  vec2 q = gl_PointCoord * 2.0 - 1.0;
  float d = dot(q, q);
  if (d > 1.0) discard;
  float core = pow(max(0.0, 1.0 - d), 3.5);
  float halo = pow(max(0.0, 1.0 - d), 1.1) * 0.35;
  // cross-flare on the brightest stars
  float flare = max(0.0, 1.0 - abs(q.x) * 9.0) + max(0.0, 1.0 - abs(q.y) * 9.0);
  flare *= smoothstep(0.75, 1.0, vTwinkle) * 0.28;
  float a = (core + halo + flare) * vTwinkle * uOpacity;
  if (a <= 0.003) discard;
  gl_FragColor = vec4(vTint * (0.85 + core * 1.6), a);
}
`;

const DUST_VERT = /* glsl */ `
attribute float aSize;
attribute float aPhase;
uniform float uTime;
uniform float uPixelRatio;
uniform float uSpan;
varying float vFade;
void main() {
  vec3 p = position;
  float drift = uTime * (0.08 + aPhase * 0.16);
  p.x = mod(p.x + drift, uSpan * 2.0) - uSpan;
  p.y += sin(uTime * 0.25 + aPhase * 41.0) * 0.7;
  p.z = mod(p.z + drift * 0.4, uSpan * 2.0) - uSpan;
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  float dist = -mv.z;
  vFade = smoothstep(2.0, 14.0, dist) * (1.0 - smoothstep(60.0, 150.0, dist));
  gl_PointSize = aSize * uPixelRatio * (26.0 / max(0.4, dist));
  gl_Position = projectionMatrix * mv;
}
`;

const DUST_FRAG = /* glsl */ `
precision highp float;
uniform vec3 uColor;
uniform float uOpacity;
varying float vFade;
void main() {
  vec2 q = gl_PointCoord * 2.0 - 1.0;
  float d = dot(q, q);
  if (d > 1.0) discard;
  float a = pow(max(0.0, 1.0 - d), 2.2) * vFade * uOpacity;
  if (a <= 0.002) discard;
  gl_FragColor = vec4(uColor, a);
}
`;

export interface SpaceBackdropOptions {
  quality?: Quality;
  /** Radius of the backdrop sphere; defaults to just inside the camera far plane. */
  radius?: number;
  /** Half-extent of the dust volume in world units. */
  dustSpan?: number;
  pixelRatio?: number;
}

export class SpaceBackdrop {
  readonly group: THREE.Group;

  private readonly nebula: THREE.Mesh;
  private readonly nebulaMat: FxMaterial;
  private readonly stars: THREE.Points;
  private readonly starMat: FxMaterial;
  private readonly dust: THREE.Points | null = null;
  private readonly dustMat: FxMaterial | null = null;
  private readonly starGroup: THREE.Group;
  private readonly quality: Quality;
  private time = 0;

  constructor(scene: THREE.Object3D, opts: SpaceBackdropOptions = {}) {
    this.quality = opts.quality ?? 'high';
    const radius = opts.radius ?? MAP_VIEW.camera.far * 0.46;
    const pixelRatio = opts.pixelRatio ?? 1;
    const dustSpan = opts.dustSpan ?? 70;

    this.group = new THREE.Group();
    this.group.name = 'space';
    this.group.renderOrder = -1000;
    scene.add(this.group);

    // ── nebula shell ─────────────────────────────────────────────────────────
    const segs = this.quality === 'low' ? 24 : this.quality === 'medium' ? 36 : 48;
    const sphere = new THREE.SphereGeometry(radius, segs, Math.round(segs * 0.66));
    this.nebulaMat = registerMaterial(
      new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0 },
          uDeep: { value: new THREE.Color(0x02030a) },
          uIndigo: { value: new THREE.Color(0x141d4a).multiplyScalar(0.5) },
          uTeal: { value: new THREE.Color(0x0d3f4d).multiplyScalar(0.42) },
          uBand: { value: new THREE.Color(0x3a4f8a).multiplyScalar(0.26) },
          uIntensity: { value: this.quality === 'low' ? 0.8 : 0.92 },
        },
        vertexShader: NEBULA_VERT,
        fragmentShader: NEBULA_FRAG,
        side: THREE.BackSide,
        depthWrite: false,
        depthTest: false,
        fog: false,
      }),
    );
    this.nebulaMat.name = 'tb.nebula';
    this.nebula = new THREE.Mesh(sphere, this.nebulaMat);
    this.nebula.frustumCulled = false;
    this.nebula.renderOrder = -1000;
    this.nebula.matrixAutoUpdate = true;
    this.group.add(this.nebula);

    // ── starfield ────────────────────────────────────────────────────────────
    this.starGroup = new THREE.Group();
    this.starGroup.renderOrder = -900;
    this.group.add(this.starGroup);

    const starCount = Math.round(
      MAP_VIEW.starCount * (this.quality === 'low' ? 0.32 : this.quality === 'medium' ? 0.65 : 1),
    );
    const starGeo = new THREE.BufferGeometry();
    const sPos = new Float32Array(starCount * 3);
    const sSize = new Float32Array(starCount);
    const sPhase = new Float32Array(starCount);
    const sTint = new Float32Array(starCount * 3);
    const tint = new THREE.Color();
    const shell = radius * 0.9;
    for (let i = 0; i < starCount; i++) {
      // uniform points on a sphere
      const u = Math.random() * 2 - 1;
      const th = Math.random() * Math.PI * 2;
      const s = Math.sqrt(Math.max(0, 1 - u * u));
      sPos[i * 3 + 0] = Math.cos(th) * s * shell;
      sPos[i * 3 + 1] = u * shell;
      sPos[i * 3 + 2] = Math.sin(th) * s * shell;

      const r = Math.random();
      sSize[i] = r > 0.985 ? 5.4 : r > 0.9 ? 3.1 : r > 0.65 ? 2.0 : 1.35;
      sPhase[i] = Math.random();

      // colour temperature ramp: cold blue-white → warm gold on a few
      const warm = Math.random();
      if (warm > 0.93) tint.setHSL(0.09, 0.55, 0.72);
      else if (warm > 0.78) tint.setHSL(0.55, 0.35, 0.78);
      else tint.setHSL(0.58, 0.18, 0.88);
      sTint[i * 3 + 0] = tint.r;
      sTint[i * 3 + 1] = tint.g;
      sTint[i * 3 + 2] = tint.b;
    }
    starGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3));
    starGeo.setAttribute('aSize', new THREE.BufferAttribute(sSize, 1));
    starGeo.setAttribute('aPhase', new THREE.BufferAttribute(sPhase, 1));
    starGeo.setAttribute('aTint', new THREE.BufferAttribute(sTint, 3));
    starGeo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), shell * 1.1);

    this.starMat = registerMaterial(
      new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0 },
          uPixelRatio: { value: pixelRatio },
          uOpacity: { value: this.quality === 'low' ? 0.6 : 0.72 },
        },
        vertexShader: STAR_VERT,
        fragmentShader: STAR_FRAG,
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        depthTest: false,
      }),
    );
    this.starMat.name = 'tb.stars';
    this.stars = new THREE.Points(starGeo, this.starMat);
    this.stars.frustumCulled = false;
    this.stars.renderOrder = -900;
    this.starGroup.add(this.stars);

    // ── dust motes (skipped on low) ──────────────────────────────────────────
    if (this.quality !== 'low' && MAP_VIEW.dustCount > 0) {
      const dustCount = Math.round(MAP_VIEW.dustCount * (this.quality === 'medium' ? 0.5 : 1));
      const dGeo = new THREE.BufferGeometry();
      const dPos = new Float32Array(dustCount * 3);
      const dSize = new Float32Array(dustCount);
      const dPhase = new Float32Array(dustCount);
      for (let i = 0; i < dustCount; i++) {
        dPos[i * 3 + 0] = (Math.random() * 2 - 1) * dustSpan;
        dPos[i * 3 + 1] = Math.random() * 26 - 3;
        dPos[i * 3 + 2] = (Math.random() * 2 - 1) * dustSpan;
        dSize[i] = 0.5 + Math.random() * 1.6;
        dPhase[i] = Math.random();
      }
      dGeo.setAttribute('position', new THREE.BufferAttribute(dPos, 3));
      dGeo.setAttribute('aSize', new THREE.BufferAttribute(dSize, 1));
      dGeo.setAttribute('aPhase', new THREE.BufferAttribute(dPhase, 1));
      dGeo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), dustSpan * 2);

      this.dustMat = registerMaterial(
        new THREE.ShaderMaterial({
          uniforms: {
            uTime: { value: 0 },
            uPixelRatio: { value: pixelRatio },
            uSpan: { value: dustSpan },
            uColor: { value: new THREE.Color(0x6fd0ff).multiplyScalar(0.6) },
            uOpacity: { value: 0.5 },
          },
          vertexShader: DUST_VERT,
          fragmentShader: DUST_FRAG,
          transparent: true,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      );
      this.dustMat.name = 'tb.dust';
      this.dust = new THREE.Points(dGeo, this.dustMat);
      this.dust.frustumCulled = false;
      this.dust.renderOrder = -50;
      this.group.add(this.dust);
    }
  }

  /** Keeps the sky locked to the camera and rolls the starfield very slowly. */
  update(dt: number, camera: THREE.Camera): void {
    this.time += dt;
    this.nebula.position.copy(camera.position);
    this.starGroup.position.copy(camera.position);
    this.starGroup.rotation.y = this.time * 0.0035;
    this.starGroup.rotation.x = Math.sin(this.time * 0.02) * 0.012;
  }

  setPixelRatio(ratio: number): void {
    this.starMat.uniforms.uPixelRatio.value = ratio;
    if (this.dustMat) this.dustMat.uniforms.uPixelRatio.value = ratio;
  }

  dispose(): void {
    this.nebula.geometry.dispose();
    this.nebulaMat.dispose();
    this.stars.geometry.dispose();
    this.starMat.dispose();
    if (this.dust) {
      this.dust.geometry.dispose();
      this.dustMat?.dispose();
    }
    this.group.removeFromParent();
    this.group.clear();
  }
}
