/**
 * TERRA BELLUM — global-map camera rig.
 *
 * Orbit-style rig over a ground-plane target:
 *   • one finger / left drag  → pan the target with inertia
 *   • two-finger pinch        → zoom  (MAP_VIEW.camera.min/maxZoom)
 *   • two-finger twist        → azimuth
 *   • two-finger vertical drag→ tilt  (MAP_VIEW.camera.min/maxPolar)
 *   • wheel                   → zoom
 *
 * Every axis runs through a critically damped spring so nothing ever
 * overshoots or snaps. Pointer events are captured and default-prevented so the
 * page can never scroll or rubber-band underneath the canvas.
 */
import * as THREE from 'three';
import { MAP_VIEW } from '../../config/visual';

export interface MapControlsOptions {
  minZoom?: number;
  maxZoom?: number;
  startZoom?: number;
  minPolar?: number;
  maxPolar?: number;
  startPolar?: number;
  startAzimuth?: number;
  /** Max distance the target may drift from the world origin. */
  bounds?: number;
  /** Spring stiffness; higher = snappier. */
  responsiveness?: number;
}

export interface FocusOptions {
  zoom?: number;
  polar?: number;
  azimuth?: number;
  instant?: boolean;
}

type PointerRecord = {
  id: number;
  x: number;
  y: number;
  startX: number;
  startY: number;
  startTime: number;
  moved: number;
};

const TAP_MOVE_PX = 12;
const TAP_MAX_MS = 320;
const LONG_PRESS_MS = 460;
const LONG_PRESS_MOVE_PX = 14;

/** Implicit-Euler critically damped spring — unconditionally stable. */
function spring(cur: number, vel: number, goal: number, omega: number, dt: number): [number, number] {
  const f = 1 + 2 * dt * omega;
  const oo = omega * omega;
  const hoo = dt * oo;
  const hhoo = dt * hoo;
  const det = 1 / (f + hhoo);
  const pos = (cur * f + vel * dt + goal * hhoo) * det;
  const nv = (vel + hoo * (goal - cur)) * det;
  return [pos, nv];
}

export class MapControls {
  enabled = true;

  readonly target = new THREE.Vector3();

  private readonly camera: THREE.PerspectiveCamera;
  private readonly dom: HTMLElement;
  private readonly opts: Required<MapControlsOptions>;

  // spring state
  private readonly targetGoal = new THREE.Vector3();
  private readonly targetVel = new THREE.Vector3();
  private zoom: number;
  private zoomGoal: number;
  private zoomVel = 0;
  private polar: number;
  private polarGoal: number;
  private polarVel = 0;
  private azimuth: number;
  private azimuthGoal: number;
  private azimuthVel = 0;

  // inertia
  private readonly panVel = new THREE.Vector3();
  private dragging = false;

  // pointer bookkeeping
  private readonly pointers = new Map<number, PointerRecord>();
  private pinchDist = 0;
  private pinchAngle = 0;
  private pinchMidY = 0;
  private multiTouch = false;
  private longPressTimer = 0;
  private longPressFired = false;

  // callbacks
  private tapCb: ((x: number, y: number) => void) | null = null;
  private longPressCb: ((x: number, y: number) => void) | null = null;
  private hoverCb: ((x: number, y: number) => void) | null = null;
  private changeCb: (() => void) | null = null;

  // scratch — no per-frame allocation
  private readonly scratchA = new THREE.Vector3();
  private readonly scratchB = new THREE.Vector3();
  private readonly scratchC = new THREE.Vector3();
  private readonly ndc = new THREE.Vector2();
  private readonly ray = new THREE.Raycaster();
  private readonly plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);

  private disposed = false;

  constructor(camera: THREE.PerspectiveCamera, dom: HTMLElement, options: MapControlsOptions = {}) {
    this.camera = camera;
    this.dom = dom;
    const c = MAP_VIEW.camera;
    this.opts = {
      minZoom: options.minZoom ?? c.minZoom,
      maxZoom: options.maxZoom ?? c.maxZoom,
      startZoom: options.startZoom ?? c.startZoom,
      minPolar: options.minPolar ?? c.minPolar,
      maxPolar: options.maxPolar ?? c.maxPolar,
      startPolar: options.startPolar ?? c.startPolar,
      startAzimuth: options.startAzimuth ?? 0,
      bounds: options.bounds ?? 90,
      responsiveness: options.responsiveness ?? 11,
    };

    this.zoom = this.zoomGoal = this.opts.startZoom;
    this.polar = this.polarGoal = this.opts.startPolar;
    this.azimuth = this.azimuthGoal = this.opts.startAzimuth;

    dom.style.touchAction = 'none';
    (dom.style as CSSStyleDeclaration & { webkitUserSelect?: string }).webkitUserSelect = 'none';
    dom.style.userSelect = 'none';

    dom.addEventListener('pointerdown', this.onPointerDown, { passive: false });
    dom.addEventListener('pointermove', this.onPointerMove, { passive: false });
    dom.addEventListener('pointerup', this.onPointerUp, { passive: false });
    dom.addEventListener('pointercancel', this.onPointerUp, { passive: false });
    dom.addEventListener('pointerleave', this.onPointerLeave, { passive: false });
    dom.addEventListener('wheel', this.onWheel, { passive: false });
    dom.addEventListener('contextmenu', this.onContextMenu, { passive: false });
    dom.addEventListener('touchstart', this.preventTouch, { passive: false });
    dom.addEventListener('touchmove', this.preventTouch, { passive: false });

    this.applyCamera();
  }

  // ── public API ────────────────────────────────────────────────────────────

  onTap(cb: (x: number, y: number) => void): void {
    this.tapCb = cb;
  }

  onLongPress(cb: (x: number, y: number) => void): void {
    this.longPressCb = cb;
  }

  onHover(cb: (x: number, y: number) => void): void {
    this.hoverCb = cb;
  }

  onChange(cb: () => void): void {
    this.changeCb = cb;
  }

  /** Flies the rig to a world position. */
  focus(worldPos: THREE.Vector3, opts: FocusOptions = {}): void {
    this.targetGoal.set(worldPos.x, 0, worldPos.z);
    this.clampTarget(this.targetGoal);
    this.panVel.set(0, 0, 0);
    if (opts.zoom !== undefined) {
      this.zoomGoal = THREE.MathUtils.clamp(opts.zoom, this.opts.minZoom, this.opts.maxZoom);
    }
    if (opts.polar !== undefined) {
      this.polarGoal = THREE.MathUtils.clamp(opts.polar, this.opts.minPolar, this.opts.maxPolar);
    }
    if (opts.azimuth !== undefined) this.azimuthGoal = opts.azimuth;
    if (opts.instant) {
      this.target.copy(this.targetGoal);
      this.targetVel.set(0, 0, 0);
      this.zoom = this.zoomGoal;
      this.zoomVel = 0;
      this.polar = this.polarGoal;
      this.polarVel = 0;
      this.azimuth = this.azimuthGoal;
      this.azimuthVel = 0;
      this.applyCamera();
    }
  }

  /** Current zoom (camera distance from the target). */
  get distance(): number {
    return this.zoom;
  }

  setBounds(radius: number): void {
    this.opts.bounds = radius;
  }

  /** Projects a client-space point onto the y = 0 ground plane. */
  screenToGround(clientX: number, clientY: number, out?: THREE.Vector3): THREE.Vector3 | null {
    const rect = this.dom.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return null;
    this.ndc.set(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -((clientY - rect.top) / rect.height) * 2 + 1,
    );
    this.ray.setFromCamera(this.ndc, this.camera);
    const dest = out ?? this.scratchC;
    const hit = this.ray.ray.intersectPlane(this.plane, dest);
    return hit ? dest : null;
  }

  /** Client-space point → normalised device coordinates. */
  toNdc(clientX: number, clientY: number, out: THREE.Vector2): THREE.Vector2 {
    const rect = this.dom.getBoundingClientRect();
    out.set(
      ((clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1,
      -((clientY - rect.top) / Math.max(1, rect.height)) * 2 + 1,
    );
    return out;
  }

  update(dt: number): void {
    if (this.disposed) return;
    const step = Math.min(0.05, Math.max(0.0005, dt));

    // pan inertia
    if (!this.dragging && this.panVel.lengthSq() > 1e-7) {
      this.targetGoal.addScaledVector(this.panVel, step);
      this.clampTarget(this.targetGoal);
      this.panVel.multiplyScalar(Math.exp(-3.4 * step));
    }

    const w = this.opts.responsiveness;
    const [tx, tvx] = spring(this.target.x, this.targetVel.x, this.targetGoal.x, w, step);
    const [tz, tvz] = spring(this.target.z, this.targetVel.z, this.targetGoal.z, w, step);
    this.target.x = tx;
    this.target.z = tz;
    this.targetVel.x = tvx;
    this.targetVel.z = tvz;

    const [z, zv] = spring(this.zoom, this.zoomVel, this.zoomGoal, w * 0.85, step);
    this.zoom = z;
    this.zoomVel = zv;

    const [p, pv] = spring(this.polar, this.polarVel, this.polarGoal, w * 0.9, step);
    this.polar = p;
    this.polarVel = pv;

    const [a, av] = spring(this.azimuth, this.azimuthVel, this.azimuthGoal, w * 0.9, step);
    this.azimuth = a;
    this.azimuthVel = av;

    this.applyCamera();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    const dom = this.dom;
    dom.removeEventListener('pointerdown', this.onPointerDown);
    dom.removeEventListener('pointermove', this.onPointerMove);
    dom.removeEventListener('pointerup', this.onPointerUp);
    dom.removeEventListener('pointercancel', this.onPointerUp);
    dom.removeEventListener('pointerleave', this.onPointerLeave);
    dom.removeEventListener('wheel', this.onWheel);
    dom.removeEventListener('contextmenu', this.onContextMenu);
    dom.removeEventListener('touchstart', this.preventTouch);
    dom.removeEventListener('touchmove', this.preventTouch);
    if (this.longPressTimer) window.clearTimeout(this.longPressTimer);
    this.pointers.clear();
    this.tapCb = null;
    this.longPressCb = null;
    this.hoverCb = null;
    this.changeCb = null;
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private clampTarget(v: THREE.Vector3): void {
    v.y = 0;
    const r = this.opts.bounds;
    const len = Math.hypot(v.x, v.z);
    if (len > r) {
      v.x = (v.x / len) * r;
      v.z = (v.z / len) * r;
    }
  }

  private applyCamera(): void {
    const sinP = Math.sin(this.polar);
    const cosP = Math.cos(this.polar);
    this.scratchA.set(sinP * Math.sin(this.azimuth), cosP, sinP * Math.cos(this.azimuth));
    this.camera.position.copy(this.target).addScaledVector(this.scratchA, this.zoom);
    this.camera.up.set(0, 1, 0);
    this.camera.lookAt(this.target);
    this.camera.updateMatrixWorld();
  }

  private cancelLongPress(): void {
    if (this.longPressTimer) {
      window.clearTimeout(this.longPressTimer);
      this.longPressTimer = 0;
    }
  }

  private readonly preventTouch = (ev: Event): void => {
    ev.preventDefault();
  };

  private readonly onContextMenu = (ev: Event): void => {
    ev.preventDefault();
  };

  private readonly onPointerDown = (ev: PointerEvent): void => {
    if (!this.enabled) return;
    ev.preventDefault();
    this.dom.setPointerCapture?.(ev.pointerId);
    this.pointers.set(ev.pointerId, {
      id: ev.pointerId,
      x: ev.clientX,
      y: ev.clientY,
      startX: ev.clientX,
      startY: ev.clientY,
      startTime: performance.now(),
      moved: 0,
    });

    if (this.pointers.size === 1) {
      this.dragging = true;
      this.multiTouch = false;
      this.longPressFired = false;
      this.panVel.set(0, 0, 0);
      this.targetVel.multiplyScalar(0.2);
      this.cancelLongPress();
      const cx = ev.clientX;
      const cy = ev.clientY;
      this.longPressTimer = window.setTimeout(() => {
        this.longPressTimer = 0;
        const rec = this.pointers.get(ev.pointerId);
        if (!rec || rec.moved > LONG_PRESS_MOVE_PX || this.multiTouch) return;
        this.longPressFired = true;
        this.longPressCb?.(cx, cy);
      }, LONG_PRESS_MS);
    } else if (this.pointers.size === 2) {
      this.multiTouch = true;
      this.dragging = false;
      this.cancelLongPress();
      this.beginPinch();
    }
  };

  private beginPinch(): void {
    const [a, b] = Array.from(this.pointers.values());
    if (!a || !b) return;
    this.pinchDist = Math.max(1, Math.hypot(b.x - a.x, b.y - a.y));
    this.pinchAngle = Math.atan2(b.y - a.y, b.x - a.x);
    this.pinchMidY = (a.y + b.y) * 0.5;
  }

  private readonly onPointerMove = (ev: PointerEvent): void => {
    if (!this.enabled) return;
    const rec = this.pointers.get(ev.pointerId);

    if (!rec) {
      // hover (mouse only — touch never generates a buttonless move)
      if (ev.pointerType === 'mouse' && this.pointers.size === 0) {
        this.hoverCb?.(ev.clientX, ev.clientY);
      }
      return;
    }

    ev.preventDefault();
    const dx = ev.clientX - rec.x;
    const dy = ev.clientY - rec.y;
    rec.x = ev.clientX;
    rec.y = ev.clientY;
    rec.moved += Math.hypot(dx, dy);
    if (rec.moved > LONG_PRESS_MOVE_PX) this.cancelLongPress();

    if (this.pointers.size === 1 && this.dragging) {
      this.pan(dx, dy);
    } else if (this.pointers.size >= 2) {
      this.pinch();
    }
    this.changeCb?.();
  };

  private pan(dxPx: number, dyPx: number): void {
    const rect = this.dom.getBoundingClientRect();
    const h = Math.max(1, rect.height);
    const vFov = (this.camera.fov * Math.PI) / 180;
    // world units covered by one screen pixel at the target's depth
    const worldPerPx = (2 * this.zoom * Math.tan(vFov * 0.5)) / h;
    // screen-vertical motion is foreshortened by the tilt
    const tiltScale = 1 / Math.max(0.22, Math.cos(this.polar));

    const sinA = Math.sin(this.azimuth);
    const cosA = Math.cos(this.azimuth);
    // camera right on the ground plane
    this.scratchA.set(cosA, 0, -sinA);
    // camera forward projected onto the ground plane
    this.scratchB.set(-sinA, 0, -cosA);

    const mx = -dxPx * worldPerPx;
    const my = dyPx * worldPerPx * tiltScale;

    this.scratchC.set(0, 0, 0);
    this.scratchC.addScaledVector(this.scratchA, mx);
    this.scratchC.addScaledVector(this.scratchB, my);

    this.targetGoal.add(this.scratchC);
    this.clampTarget(this.targetGoal);

    // inertia sample (world units per second, damped toward the latest push)
    this.panVel.multiplyScalar(0.62).addScaledVector(this.scratchC, 0.38 * 60);
  }

  private pinch(): void {
    const it = this.pointers.values();
    const a = it.next().value as PointerRecord | undefined;
    const b = it.next().value as PointerRecord | undefined;
    if (!a || !b) return;

    const dist = Math.max(1, Math.hypot(b.x - a.x, b.y - a.y));
    const angle = Math.atan2(b.y - a.y, b.x - a.x);
    const midY = (a.y + b.y) * 0.5;

    // zoom
    const ratio = this.pinchDist / dist;
    this.zoomGoal = THREE.MathUtils.clamp(
      this.zoomGoal * ratio,
      this.opts.minZoom,
      this.opts.maxZoom,
    );

    // twist → azimuth
    let dAngle = angle - this.pinchAngle;
    while (dAngle > Math.PI) dAngle -= Math.PI * 2;
    while (dAngle < -Math.PI) dAngle += Math.PI * 2;
    this.azimuthGoal -= dAngle;

    // vertical two-finger drag → tilt
    const dMid = midY - this.pinchMidY;
    this.polarGoal = THREE.MathUtils.clamp(
      this.polarGoal + dMid * 0.0042,
      this.opts.minPolar,
      this.opts.maxPolar,
    );

    this.pinchDist = dist;
    this.pinchAngle = angle;
    this.pinchMidY = midY;
  }

  private readonly onPointerUp = (ev: PointerEvent): void => {
    const rec = this.pointers.get(ev.pointerId);
    this.pointers.delete(ev.pointerId);
    try {
      this.dom.releasePointerCapture?.(ev.pointerId);
    } catch {
      /* pointer already released */
    }
    this.cancelLongPress();

    if (this.pointers.size === 1) {
      // dropped from two fingers to one — restart the drag cleanly
      const remaining = this.pointers.values().next().value as PointerRecord | undefined;
      if (remaining) {
        remaining.moved = LONG_PRESS_MOVE_PX + 1;
        this.dragging = true;
      }
    } else if (this.pointers.size === 0) {
      this.dragging = false;
      const wasMulti = this.multiTouch;
      this.multiTouch = false;
      if (
        rec &&
        !wasMulti &&
        !this.longPressFired &&
        rec.moved <= TAP_MOVE_PX &&
        performance.now() - rec.startTime <= TAP_MAX_MS
      ) {
        this.panVel.set(0, 0, 0);
        this.tapCb?.(ev.clientX, ev.clientY);
      }
      this.longPressFired = false;
    } else {
      this.beginPinch();
    }
  };

  private readonly onPointerLeave = (ev: PointerEvent): void => {
    if (ev.pointerType === 'mouse' && this.pointers.size === 0) this.hoverCb?.(-1, -1);
  };

  private readonly onWheel = (ev: WheelEvent): void => {
    if (!this.enabled) return;
    ev.preventDefault();
    const unit = ev.deltaMode === 1 ? 18 : ev.deltaMode === 2 ? 400 : 1;
    const delta = ev.deltaY * unit;
    this.zoomGoal = THREE.MathUtils.clamp(
      this.zoomGoal * Math.exp(delta * 0.0011),
      this.opts.minZoom,
      this.opts.maxZoom,
    );
    this.changeCb?.();
  };
}
