/**
 * TERRA BELLUM — army / drone tokens on the global map.
 *
 * Everything here is instanced: chevrons, ground shadows, hostile auras, count
 * badges and drone motes are one draw call each. Movement is interpolated on
 * the GPU-side transform from `movingFrom → hexId` using `departedAt`/
 * `arrivesAt` measured against a SimClock (the world may run compressed, so the
 * clock learns the game-time/wall-time ratio from successive syncs).
 */
import * as THREE from 'three';
import type { ArmyId, GameState, GuildId, HexId, PlayerId, Terrain } from '../../game/types';
import type { ViewState } from '../../game/store';
import { PALETTE, GUILD_COLORS, MAP_VIEW } from '../../config';
import {
  InstancedBatch,
  armyChevronGeometry,
  billboardQuadGeometry,
  buildRibbon,
  groundQuadGeometry,
  moteGeometry,
} from '../core/geometry';
import {
  makeAtlasBillboardMaterial,
  makeDecalMaterial,
  makeGlowSpriteMaterial,
  makeHoloLineMaterial,
  makeTokenMaterial,
  type FxMaterial,
} from '../core/materials';
import { SimClock, type Quality } from '../core/stage';
import { hexTopY } from './hexField';
import { axialToWorld, parseHexId } from '../../game/hex';

const HEX_R = MAP_VIEW.hexRadius;
const MAX_TRAILS = 64;
const TOKEN_HOVER = 0.42;
const BADGE_MAX = 40;

const M4 = new THREE.Matrix4();
const QUAT = new THREE.Quaternion();
const UP = new THREE.Vector3(0, 1, 0);
const SCALE = new THREE.Vector3(1, 1, 1);
const POS = new THREE.Vector3();
const DIR = new THREE.Vector3();
const SIDE = new THREE.Vector3();
const TAIL = new THREE.Vector3();
const COL = new THREE.Color();

interface TokenEntry {
  id: string;
  kind: 'army' | 'drone';
  fromX: number;
  fromZ: number;
  fromY: number;
  toX: number;
  toZ: number;
  toY: number;
  departedAt: number;
  arrivesAt: number;
  moving: boolean;
  r: number;
  g: number;
  b: number;
  count: number;
  hostile: boolean;
  mine: boolean;
  seed: number;
  siege: boolean;
}

function worldOfHex(hexId: HexId, terrain: Terrain, out: THREE.Vector3): THREE.Vector3 {
  const a = parseHexId(hexId);
  const w = axialToWorld(a, HEX_R);
  return out.set(w.x, hexTopY(terrain), w.z);
}

function hashSeed(key: string): number {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 10000) / 10000;
}

// ─────────────────────────────────────────────────────────────────────────────
// Count badge atlas — one canvas texture, one draw call for every badge
// ─────────────────────────────────────────────────────────────────────────────

interface AtlasTile {
  u0: number;
  v0: number;
  du: number;
  dv: number;
  aspect: number;
}

function buildCountAtlas(): { texture: THREE.CanvasTexture; tiles: AtlasTile[] } {
  const cols = 8;
  const rows = 8;
  const cell = 64;
  const size = cols * cell;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const tiles: AtlasTile[] = [];

  if (ctx) {
    ctx.clearRect(0, 0, size, size);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (let i = 0; i <= BADGE_MAX; i++) {
      const cx = (i % cols) * cell;
      const cy = Math.floor(i / cols) * cell;
      const label = i === BADGE_MAX ? `${BADGE_MAX}+` : String(i + 1);
      const w = cell * 0.86;
      const h = cell * 0.5;
      const x = cx + (cell - w) / 2;
      const y = cy + (cell - h) / 2;

      ctx.save();
      // chip
      ctx.beginPath();
      const r = h * 0.42;
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + r);
      ctx.lineTo(x + w, y + h - r);
      ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
      ctx.lineTo(x + r, y + h);
      ctx.quadraticCurveTo(x, y + h, x, y + h - r);
      ctx.lineTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.closePath();
      ctx.fillStyle = 'rgba(255,255,255,0.14)';
      ctx.fill();
      ctx.lineWidth = 2.2;
      ctx.strokeStyle = 'rgba(255,255,255,0.92)';
      ctx.stroke();

      ctx.font = '700 26px ui-monospace, "SF Mono", Menlo, Consolas, monospace';
      ctx.fillStyle = '#ffffff';
      ctx.fillText(label, cx + cell / 2, cy + cell / 2 + 1);
      ctx.restore();

      tiles.push({
        u0: cx / size,
        v0: 1 - (cy + cell) / size,
        du: cell / size,
        dv: cell / size,
        aspect: 1,
      });
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = true;
  texture.needsUpdate = true;
  return { texture, tiles };
}

// ─────────────────────────────────────────────────────────────────────────────
// ArmyTokens
// ─────────────────────────────────────────────────────────────────────────────

export class ArmyTokens {
  readonly group = new THREE.Group();
  readonly clock = new SimClock();

  private readonly chevronMat: FxMaterial;
  private readonly shadowMat: FxMaterial;
  private readonly auraMat: FxMaterial;
  private readonly badgeMat: FxMaterial;
  private readonly moteMat: FxMaterial;
  private readonly trailMat: FxMaterial;
  private readonly pathMat: FxMaterial;
  private readonly previewMat: FxMaterial;

  private readonly chevrons: InstancedBatch;
  private readonly shadows: InstancedBatch;
  private readonly auras: InstancedBatch;
  private readonly badges: InstancedBatch;
  private readonly motes: InstancedBatch;

  private readonly badgeTexture: THREE.CanvasTexture;
  private readonly badgeTiles: AtlasTile[];

  private readonly trailGeo: THREE.BufferGeometry;
  private readonly trailPos: Float32Array;
  private readonly trailCol: Float32Array;
  private readonly trailMesh: THREE.Mesh;

  private pathMesh: THREE.Mesh | null = null;
  private previewMesh: THREE.Mesh | null = null;
  private pathSig = '';
  private previewSig = '';
  private pathLength = 1;

  private entries: TokenEntry[] = [];
  private elapsed = 0;
  private readonly quality: Quality;

  constructor(quality: Quality = 'high') {
    this.quality = quality;
    this.group.name = 'tokens';

    this.chevronMat = makeTokenMaterial(0xffffff, { emissive: 2.1 });
    this.shadowMat = makeDecalMaterial(0x000000, {
      additive: false,
      softness: 2.9,
      opacity: 0.62,
    });
    this.auraMat = makeGlowSpriteMaterial(0xffffff, 2.9);
    this.auraMat.uniforms.uCore.value = 0.25;
    this.moteMat = makeTokenMaterial(PALETTE.violet, { translucent: true, emissive: 1.5 });
    this.trailMat = makeHoloLineMaterial(0xffffff, { opacity: 0.11 });
    this.pathMat = makeHoloLineMaterial(PALETTE.cyan, {
      opacity: 0.65,
      dash: true,
      dashSize: 0.5,
      gapSize: 0.36,
      dashSpeed: 1.6,
      headWidth: 0.85,
    });
    this.previewMat = makeHoloLineMaterial(PALETTE.gold, {
      opacity: 0.6,
      dash: true,
      dashSize: 0.34,
      gapSize: 0.3,
      dashSpeed: 2.4,
      headWidth: 0.6,
    });

    const atlas = buildCountAtlas();
    this.badgeTexture = atlas.texture;
    this.badgeTiles = atlas.tiles;
    this.badgeMat = makeAtlasBillboardMaterial(this.badgeTexture, false);

    const attrsColorAux = [
      { name: 'iColor', size: 3, fill: [1, 1, 1] },
      { name: 'iAux', size: 3, fill: [1, 0, 0] },
    ];

    this.shadows = new InstancedBatch(
      this.group,
      groundQuadGeometry(1),
      this.shadowMat,
      64,
      attrsColorAux,
    );
    this.shadows.setRenderOrder(5);

    this.auras = new InstancedBatch(
      this.group,
      billboardQuadGeometry(1),
      this.auraMat,
      64,
      attrsColorAux,
    );
    this.auras.setRenderOrder(9);

    this.chevrons = new InstancedBatch(
      this.group,
      armyChevronGeometry(0.58),
      this.chevronMat,
      64,
      attrsColorAux,
    );
    this.chevrons.setRenderOrder(10);

    this.motes = new InstancedBatch(
      this.group,
      moteGeometry(0.19),
      this.moteMat,
      48,
      attrsColorAux,
    );
    this.motes.setRenderOrder(11);

    this.badges = new InstancedBatch(this.group, billboardQuadGeometry(1), this.badgeMat, 64, [
      { name: 'iRect', size: 4, fill: [0, 0, 1, 1] },
      { name: 'iAux', size: 3, fill: [1, 1, 1] },
      { name: 'iColor', size: 3, fill: [1, 1, 1] },
    ]);
    this.badges.setRenderOrder(20);

    // ── trail ribbon pool: MAX_TRAILS tapered quads in one geometry ─────────
    const verts = MAX_TRAILS * 4;
    this.trailPos = new Float32Array(verts * 3);
    this.trailCol = new Float32Array(verts * 3);
    const uv = new Float32Array(verts * 2);
    const dist = new Float32Array(verts);
    const index: number[] = [];
    for (let t = 0; t < MAX_TRAILS; t++) {
      const b = t * 4;
      // 0,1 = tail (left,right)  2,3 = head (left,right)
      uv[(b + 0) * 2 + 0] = 0;
      uv[(b + 0) * 2 + 1] = 0;
      uv[(b + 1) * 2 + 0] = 0;
      uv[(b + 1) * 2 + 1] = 1;
      uv[(b + 2) * 2 + 0] = 1;
      uv[(b + 2) * 2 + 1] = 0;
      uv[(b + 3) * 2 + 0] = 1;
      uv[(b + 3) * 2 + 1] = 1;
      index.push(b, b + 1, b + 3, b, b + 3, b + 2);
    }
    this.trailGeo = new THREE.BufferGeometry();
    const posAttr = new THREE.BufferAttribute(this.trailPos, 3);
    posAttr.setUsage(THREE.DynamicDrawUsage);
    const colAttr = new THREE.BufferAttribute(this.trailCol, 3);
    colAttr.setUsage(THREE.DynamicDrawUsage);
    this.trailGeo.setAttribute('position', posAttr);
    this.trailGeo.setAttribute('aColor', colAttr);
    this.trailGeo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    this.trailGeo.setAttribute('aDist', new THREE.BufferAttribute(dist, 1));
    this.trailGeo.setAttribute(
      'normal',
      new THREE.BufferAttribute(new Float32Array(verts * 3).fill(0), 3),
    );
    this.trailGeo.setIndex(index);
    this.trailGeo.setDrawRange(0, 0);
    this.trailMesh = new THREE.Mesh(this.trailGeo, this.trailMat);
    this.trailMesh.frustumCulled = false;
    this.trailMesh.renderOrder = 8;
    this.group.add(this.trailMesh);
  }

  // ── state sync ────────────────────────────────────────────────────────────

  sync(state: GameState, view: ViewState): void {
    this.clock.sync(state.now);

    const meId: PlayerId = state.meId;
    const myGuild: GuildId | undefined = state.players[meId]?.guildId;
    const entries: TokenEntry[] = [];

    for (const army of Object.values(state.armies)) {
      const dest = state.world.hexes[army.hexId];
      if (!dest) continue;
      worldOfHex(army.hexId, dest.terrain, POS);
      const toX = POS.x;
      const toY = POS.y;
      const toZ = POS.z;

      let fromX = toX;
      let fromY = toY;
      let fromZ = toZ;
      const moving =
        army.movingFrom !== undefined &&
        army.departedAt !== undefined &&
        army.arrivesAt !== undefined &&
        army.arrivesAt > army.departedAt;
      if (moving && army.movingFrom) {
        const src = state.world.hexes[army.movingFrom];
        worldOfHex(army.movingFrom, src ? src.terrain : 'plains', POS);
        fromX = POS.x;
        fromY = POS.y;
        fromZ = POS.z;
      }

      const guild = army.guildId ? state.guilds[army.guildId] : undefined;
      COL.setHex(guild ? guild.color : GUILD_COLORS[0]);
      const mine = army.ownerId === meId;
      const friendly = mine || (myGuild !== undefined && army.guildId === myGuild);

      entries.push({
        id: army.id,
        kind: 'army',
        fromX,
        fromY,
        fromZ,
        toX,
        toY,
        toZ,
        departedAt: army.departedAt ?? 0,
        arrivesAt: army.arrivesAt ?? 0,
        moving,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        count: army.units.length,
        hostile: !friendly,
        mine,
        seed: hashSeed(army.id),
        siege: army.siege !== undefined,
      });
    }

    for (const drone of Object.values(state.drones)) {
      if (!drone.alive) continue;
      const friendly =
        drone.ownerId === meId || (myGuild !== undefined && drone.guildId === myGuild);
      if (!friendly) continue;
      const dest = state.world.hexes[drone.hexId];
      if (!dest) continue;
      worldOfHex(drone.hexId, dest.terrain, POS);
      const toX = POS.x;
      const toY = POS.y;
      const toZ = POS.z;
      let fromX = toX;
      let fromY = toY;
      let fromZ = toZ;
      const moving =
        drone.movingFrom !== undefined &&
        drone.departedAt !== undefined &&
        drone.arrivesAt !== undefined &&
        drone.arrivesAt > drone.departedAt;
      if (moving && drone.movingFrom) {
        const src = state.world.hexes[drone.movingFrom];
        worldOfHex(drone.movingFrom, src ? src.terrain : 'plains', POS);
        fromX = POS.x;
        fromY = POS.y;
        fromZ = POS.z;
      }
      COL.setHex(PALETTE.violet);
      entries.push({
        id: drone.id,
        kind: 'drone',
        fromX,
        fromY,
        fromZ,
        toX,
        toY,
        toZ,
        departedAt: drone.departedAt ?? 0,
        arrivesAt: drone.arrivesAt ?? 0,
        moving,
        r: COL.r,
        g: COL.g,
        b: COL.b,
        count: 1,
        hostile: false,
        mine: drone.ownerId === meId,
        seed: hashSeed(drone.id),
        siege: false,
      });
    }

    this.entries = entries;
    this.syncPaths(state, view);
  }

  /** Rebuilds the ordered-move line and the drag preview line when they change. */
  private syncPaths(state: GameState, view: ViewState): void {
    const armyId: ArmyId | undefined = view.selectedArmyId;
    const army = armyId ? state.armies[armyId] : undefined;

    // Cheap string signature first — the ribbon is only rebuilt on real change.
    let sig = '';
    if (army && army.path.length > 0) {
      sig = army.movingFrom ?? army.hexId;
      for (const step of army.path) sig += `>${step.hexId}`;
    }
    if (sig !== this.pathSig) {
      this.pathSig = sig;
      this.disposePathMesh();
      if (army && army.path.length > 0) {
        const pts: THREE.Vector3[] = [];
        const head = army.movingFrom ?? army.hexId;
        const headHex = state.world.hexes[head];
        const v0 = worldOfHex(head, headHex ? headHex.terrain : 'plains', new THREE.Vector3());
        v0.y += 0.16;
        pts.push(v0);
        for (const step of army.path) {
          const hex = state.world.hexes[step.hexId];
          const v = worldOfHex(step.hexId, hex ? hex.terrain : 'plains', new THREE.Vector3());
          v.y += 0.16;
          pts.push(v);
        }
        if (pts.length > 1) {
          const geo = buildRibbon(pts, 0.2);
          this.pathLength = Math.max(0.001, geo.userData.length as number);
          this.pathMesh = new THREE.Mesh(geo, this.pathMat);
          this.pathMesh.frustumCulled = false;
          this.pathMesh.renderOrder = 7;
          this.group.add(this.pathMesh);
        }
      }
    }

    // preview path (drag-to-order)
    const preview = view.previewPath;
    const psig = preview.join('>');
    if (psig !== this.previewSig) {
      this.previewSig = psig;
      this.disposePreviewMesh();
      if (preview.length > 1) {
        const pts: THREE.Vector3[] = [];
        for (const id of preview) {
          const hex = state.world.hexes[id];
          if (!hex) continue;
          const v = worldOfHex(id, hex.terrain, new THREE.Vector3());
          v.y += 0.2;
          pts.push(v);
        }
        if (pts.length > 1) {
          const geo = buildRibbon(pts, 0.16);
          this.previewMesh = new THREE.Mesh(geo, this.previewMat);
          this.previewMesh.frustumCulled = false;
          this.previewMesh.renderOrder = 7;
          this.group.add(this.previewMesh);
        }
      }
    }
  }

  // ── per-frame ─────────────────────────────────────────────────────────────

  update(dt: number): void {
    this.clock.advance(dt);
    this.elapsed += dt;
    const now = this.clock.now;
    const t = this.elapsed;

    const need = this.entries.length + 4;
    this.chevrons.ensure(need);
    this.shadows.ensure(need);
    this.auras.ensure(need);
    this.badges.ensure(need);
    this.motes.ensure(need);

    this.chevrons.begin();
    this.shadows.begin();
    this.auras.begin();
    this.badges.begin();
    this.motes.begin();

    let trailCount = 0;
    let trailDirty = false;

    for (const e of this.entries) {
      // ── interpolate position
      let p = 0;
      if (e.moving) {
        const span = e.arrivesAt - e.departedAt;
        p = span > 0 ? (now - e.departedAt) / span : 1;
        p = p < 0 ? 0 : p > 1 ? 1 : p;
      } else {
        p = 1;
      }
      const eased = e.moving ? p * p * (3 - 2 * p) * 0.35 + p * 0.65 : 1;
      const x = e.fromX + (e.toX - e.fromX) * eased;
      const z = e.fromZ + (e.toZ - e.fromZ) * eased;
      const groundY = e.fromY + (e.toY - e.fromY) * eased;

      const bob = Math.sin(t * 1.7 + e.seed * 12.6) * 0.055;
      const hover = e.kind === 'drone' ? TOKEN_HOVER * 0.75 : TOKEN_HOVER;
      const y = groundY + hover + bob;

      // ── heading
      let yaw: number;
      if (e.moving && (Math.abs(e.toX - e.fromX) > 1e-4 || Math.abs(e.toZ - e.fromZ) > 1e-4)) {
        yaw = Math.atan2(e.toX - e.fromX, e.toZ - e.fromZ);
      } else {
        yaw = e.seed * Math.PI * 2 + t * (e.kind === 'drone' ? 0.9 : 0.24);
      }

      POS.set(x, y, z);
      QUAT.setFromAxisAngle(UP, yaw);

      if (e.kind === 'drone') {
        const s = 1 + Math.sin(t * 3.1 + e.seed * 20) * 0.08;
        M4.compose(POS, QUAT, SCALE.set(s, s, s));
        const i = this.motes.add(M4);
        if (i >= 0) {
          this.motes.set(i, 'iColor', e.r, e.g, e.b);
          this.motes.set(i, 'iAux', 0.5, 0, 1);
        }
      } else {
        const tilt = e.moving ? Math.sin(t * 2.1 + e.seed * 9) * 0.06 : 0;
        QUAT.setFromAxisAngle(UP, yaw);
        M4.compose(POS, QUAT, SCALE.set(1, 1 + tilt, 1));
        const i = this.chevrons.add(M4);
        if (i >= 0) {
          this.chevrons.set(i, 'iColor', e.r, e.g, e.b);
          this.chevrons.set(i, 'iAux', 1, e.hostile ? 1 : 0, e.mine ? 0.6 : 0.2);
        }
      }

      // ── ground shadow
      POS.set(x, groundY + 0.028, z);
      const shadowScale = (e.kind === 'drone' ? 0.5 : 1.05) * (1 - bob * 0.6);
      M4.compose(POS, QUAT.identity(), SCALE.set(shadowScale, 1, shadowScale));
      const si = this.shadows.add(M4);
      if (si >= 0) {
        this.shadows.set(si, 'iColor', 1, 1, 1);
        this.shadows.set(si, 'iAux', e.kind === 'drone' ? 0.35 : 0.7, e.seed, 0);
      }

      // ── halo: soft guild glow for everyone, pulsing threat red for hostiles
      POS.set(x, groundY + hover * 0.75, z);
      M4.compose(POS, QUAT.identity(), SCALE.set(1, 1, 1));
      const ai = this.auras.add(M4);
      if (ai >= 0) {
        const pulse = 0.5 + 0.5 * Math.sin(t * 3.4 + e.seed * 11);
        if (e.hostile) {
          this.auras.set(ai, 'iColor', 1, 0.3, 0.34);
          this.auras.set(ai, 'iAux', 1.5 + pulse * 0.35, 0.16 + pulse * 0.16, e.seed);
        } else if (e.siege) {
          this.auras.set(ai, 'iColor', 1, 0.72, 0.28);
          this.auras.set(ai, 'iAux', 1.5 + pulse * 0.35, 0.16 + pulse * 0.16, e.seed);
        } else {
          this.auras.set(ai, 'iColor', e.r, e.g, e.b);
          this.auras.set(ai, 'iAux', 1.25, e.kind === 'drone' ? 0.09 : 0.14, e.seed);
        }
      }

      // ── count badge
      if (e.kind === 'army' && e.count > 1) {
        const tileIndex = Math.min(BADGE_MAX, Math.max(0, e.count - 1));
        const tile = this.badgeTiles[tileIndex];
        if (tile) {
          POS.set(x, y + 0.5, z);
          M4.compose(POS, QUAT.identity(), SCALE.set(1, 1, 1));
          const bi = this.badges.add(M4);
          if (bi >= 0) {
            this.badges.set(bi, 'iRect', tile.u0, tile.v0, tile.du, tile.dv);
            this.badges.set(bi, 'iAux', 0.62, 0.62, 0.95);
            this.badges.set(bi, 'iColor', e.r, e.g, e.b);
          }
        }
      }

      // ── travel trail ribbon
      if (e.moving && p > 0.001 && p < 0.999 && trailCount < MAX_TRAILS) {
        DIR.set(e.toX - e.fromX, 0, e.toZ - e.fromZ);
        const travelled = DIR.length() * eased;
        if (travelled > 0.02) {
          DIR.normalize();
          SIDE.set(-DIR.z, 0, DIR.x);
          const maxLen = HEX_R * 2.4;
          const len = Math.min(maxLen, travelled);
          TAIL.set(x - DIR.x * len, groundY + hover * 0.85, z - DIR.z * len);
          const b = trailCount * 4;
          const headW = 0.12;
          const tailW = 0.02;
          setVec(this.trailPos, b + 0, TAIL.x - SIDE.x * tailW, TAIL.y, TAIL.z - SIDE.z * tailW);
          setVec(this.trailPos, b + 1, TAIL.x + SIDE.x * tailW, TAIL.y, TAIL.z + SIDE.z * tailW);
          setVec(this.trailPos, b + 2, x - SIDE.x * headW, y - 0.06, z - SIDE.z * headW);
          setVec(this.trailPos, b + 3, x + SIDE.x * headW, y - 0.06, z + SIDE.z * headW);
          setVec(this.trailCol, b + 0, 0, 0, 0);
          setVec(this.trailCol, b + 1, 0, 0, 0);
          setVec(this.trailCol, b + 2, e.r, e.g, e.b);
          setVec(this.trailCol, b + 3, e.r, e.g, e.b);
          trailCount++;
          trailDirty = true;
        }
      }
    }

    this.chevrons.end();
    this.shadows.end();
    this.auras.end();
    this.badges.end();
    this.motes.end();

    this.trailGeo.setDrawRange(0, trailCount * 6);
    if (trailDirty) {
      this.trailGeo.getAttribute('position').needsUpdate = true;
      this.trailGeo.getAttribute('aColor').needsUpdate = true;
    }
    this.trailMesh.visible = trailCount > 0;

    // travelling highlight crawling along the ordered path
    if (this.pathMesh) {
      this.pathMat.uniforms.uHead.value = ((t * 2.6) % (this.pathLength + 1.6)) - 0.8;
    }
  }

  /** Number of tokens currently drawn (diagnostics). */
  get tokenCount(): number {
    return this.entries.length;
  }

  // ── teardown ──────────────────────────────────────────────────────────────

  private disposePathMesh(): void {
    if (!this.pathMesh) return;
    this.group.remove(this.pathMesh);
    this.pathMesh.geometry.dispose();
    this.pathMesh = null;
  }

  private disposePreviewMesh(): void {
    if (!this.previewMesh) return;
    this.group.remove(this.previewMesh);
    this.previewMesh.geometry.dispose();
    this.previewMesh = null;
  }

  dispose(): void {
    this.chevrons.dispose();
    this.shadows.dispose();
    this.auras.dispose();
    this.badges.dispose();
    this.motes.dispose();
    this.disposePathMesh();
    this.disposePreviewMesh();
    this.group.remove(this.trailMesh);
    this.trailGeo.dispose();
    this.badgeTexture.dispose();
    this.chevronMat.dispose();
    this.shadowMat.dispose();
    this.auraMat.dispose();
    this.badgeMat.dispose();
    this.moteMat.dispose();
    this.trailMat.dispose();
    this.pathMat.dispose();
    this.previewMat.dispose();
    this.group.removeFromParent();
    this.group.clear();
    this.entries.length = 0;
  }
}

function setVec(arr: Float32Array, index: number, x: number, y: number, z: number): void {
  arr[index * 3 + 0] = x;
  arr[index * 3 + 1] = y;
  arr[index * 3 + 2] = z;
}
