/**
 * TERRA BELLUM — the hex world.
 *
 * The entire planet is ONE InstancedMesh. Per-instance attributes carry the
 * terrain tint, the owning guild colour and a packed state vector; the shader
 * in core/materials does the rest (rim light, capture wipe, locked-sector
 * dissolve, gas pulse). `sync()` diffs against mirrored CPU arrays and only
 * flags the attributes that actually changed.
 *
 * Draw calls: 1 hex field + 1 ground + 1 ring batch + 1 gas plume batch
 * + 1 vent particle system + 3 obelisk tiers = 8.
 */
import * as THREE from 'three';
import type { GameState, Hex, HexId, PlayerId, Terrain } from '../../game/types';
import type { ViewState } from '../../game/store';
import { axialToWorld, parseHexId } from '../../game/hex';
import { MAP_VIEW, PALETTE, TERRAIN_META, GUILD_COLORS } from '../../config';
import {
  InstancedBatch,
  beaconRingGeometry,
  billboardQuadGeometry,
  hexPrismGeometry,
  obeliskGeometry,
} from '../core/geometry';
import {
  makeGlowSpriteMaterial,
  makeGroundMaterial,
  makeHexMaterial,
  makeDecalMaterial,
  makeTokenMaterial,
  makeVentParticleMaterial,
  type FxMaterial,
} from '../core/materials';
import type { Quality } from '../core/postfx';

const HEX_R = MAP_VIEW.hexRadius;
const PRISM_R = MAP_VIEW.hexRadius * (1 - MAP_VIEW.hexGap);

/** Height of a hex's top face in world units. */
export function hexTopY(terrain: Terrain): number {
  return MAP_VIEW.hexHeight[terrain] ?? MAP_VIEW.hexHeight.plains;
}

const AX_SCRATCH = { q: 0, r: 0 };

/** Axial hex id → world position on the ground plane (y = 0). */
export function hexWorld(hexId: HexId, out: THREE.Vector3): THREE.Vector3 {
  const a = parseHexId(hexId);
  AX_SCRATCH.q = a.q;
  AX_SCRATCH.r = a.r;
  const w = axialToWorld(AX_SCRATCH, HEX_R);
  return out.set(w.x, 0, w.z);
}

/** Axial hex id → world position on the hex's TOP face. */
export function hexWorldTop(hexId: HexId, terrain: Terrain, out: THREE.Vector3): THREE.Vector3 {
  hexWorld(hexId, out);
  out.y = hexTopY(terrain);
  return out;
}

const M4 = new THREE.Matrix4();
const V3 = new THREE.Vector3();
const UP = new THREE.Vector3(0, 1, 0);
const QUAT = new THREE.Quaternion();
const SCALE = new THREE.Vector3(1, 1, 1);
const COLOR = new THREE.Color();

const NEUTRAL_OWNER = new THREE.Color(PALETTE.edge).multiplyScalar(1.35);

export class HexField {
  readonly group = new THREE.Group();

  /** hexId → instance index, and the reverse. */
  private readonly indexOf = new Map<HexId, number>();
  private readonly idAt: HexId[] = [];
  private readonly terrainAt: Terrain[] = [];
  private readonly topYAt: number[] = [];

  private mesh: THREE.InstancedMesh | null = null;
  private readonly hexMat: FxMaterial;
  private readonly groundMat: FxMaterial;
  private readonly ringMat: FxMaterial;
  private readonly plumeMat: FxMaterial;
  private readonly ventMat: FxMaterial;
  private readonly obeliskMat: FxMaterial;

  private ground: THREE.Mesh | null = null;
  private rings: InstancedBatch | null = null;
  private plumes: InstancedBatch | null = null;
  private vents: THREE.Points | null = null;
  private readonly obelisks: InstancedBatch[] = [];

  // CPU mirrors of the instanced attributes (change detection)
  private ownerArr: Float32Array = new Float32Array(0);
  private stateArr: Float32Array = new Float32Array(0);
  private ownerDirty = false;
  private stateDirty = false;

  private readonly ownerColors = new Map<string, THREE.Color>();
  private built = false;
  private fortSig = '';
  private selected: HexId | null = null;
  private hovered: HexId | null = null;
  private pulse = 0;
  private readonly quality: Quality;

  constructor(quality: Quality = 'high', pixelRatio = 1) {
    this.quality = quality;
    this.group.name = 'hexField';

    this.hexMat = makeHexMaterial();
    this.groundMat = makeGroundMaterial();
    this.ringMat = makeDecalMaterial(PALETTE.cyan, { mode: 'ring', additive: true });
    this.plumeMat = makeGlowSpriteMaterial(PALETTE.teal, 2.8);
    this.ventMat = makeVentParticleMaterial(PALETTE.teal, pixelRatio);
    this.obeliskMat = makeTokenMaterial(PALETTE.cyan, { emissive: 0.62 });
    this.plumeMat.uniforms.uCore.value = 0.22;
    this.plumeMat.uniforms.uSoft.value = 3.4;

    if (quality === 'low') {
      this.hexMat.uniforms.uStrength.value = 0.75;
      this.plumeMat.uniforms.uOpacity.value = 0.7;
    }
  }

  // ── construction ──────────────────────────────────────────────────────────

  private build(state: GameState): void {
    this.teardownWorld();

    const hexes = state.world.hexes;
    const ids = Object.keys(hexes).sort();
    const n = ids.length;
    if (n === 0) return;

    const geo = hexPrismGeometry(PRISM_R, 1, 0.15).clone();
    const iColor = new Float32Array(n * 3);
    const iOwner = new Float32Array(n * 3);
    const iState = new Float32Array(n * 4);
    const iSeed = new Float32Array(n);

    const mesh = new THREE.InstancedMesh(geo, this.hexMat, n);
    mesh.name = 'hexes';
    mesh.instanceMatrix.setUsage(THREE.StaticDrawUsage);

    for (let i = 0; i < n; i++) {
      const id = ids[i];
      const hex = hexes[id];
      this.indexOf.set(id, i);
      this.idAt[i] = id;
      this.terrainAt[i] = hex.terrain;
      const top = hexTopY(hex.terrain);
      this.topYAt[i] = top;

      hexWorld(id, V3);
      SCALE.set(1, top, 1);
      M4.compose(V3, QUAT.identity(), SCALE);
      mesh.setMatrixAt(i, M4);

      const meta = TERRAIN_META[hex.terrain];
      COLOR.setHex(meta.color);
      iColor[i * 3 + 0] = COLOR.r;
      iColor[i * 3 + 1] = COLOR.g;
      iColor[i * 3 + 2] = COLOR.b;

      iOwner[i * 3 + 0] = NEUTRAL_OWNER.r;
      iOwner[i * 3 + 1] = NEUTRAL_OWNER.g;
      iOwner[i * 3 + 2] = NEUTRAL_OWNER.b;

      // fractional part = stable per-hex seed, +2.0 marks a gas vent
      const seed = pseudoRandom(id);
      iSeed[i] = seed * 0.999 + (hex.gas ? 2 : 0);
    }

    geo.setAttribute('iColor', new THREE.InstancedBufferAttribute(iColor, 3));
    const ownerAttr = new THREE.InstancedBufferAttribute(iOwner, 3);
    ownerAttr.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('iOwner', ownerAttr);
    const stateAttr = new THREE.InstancedBufferAttribute(iState, 4);
    stateAttr.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('iState', stateAttr);
    geo.setAttribute('iSeed', new THREE.InstancedBufferAttribute(iSeed, 1));

    mesh.instanceMatrix.needsUpdate = true;
    mesh.computeBoundingSphere();
    this.group.add(mesh);
    this.mesh = mesh;
    this.ownerArr = iOwner;
    this.stateArr = iState;

    this.buildGround(state);
    this.buildRings();
    this.buildGas(state);
    this.buildObelisks();
    this.built = true;
  }

  private buildGround(state: GameState): void {
    const span = (state.world.radius + 6) * HEX_R * 1.9;
    const geo = new THREE.CircleGeometry(span, 96);
    geo.rotateX(-Math.PI / 2);
    this.groundMat.uniforms.uRadius.value = span;
    const mesh = new THREE.Mesh(geo, this.groundMat);
    mesh.position.y = -0.12;
    mesh.renderOrder = -20;
    mesh.name = 'ground';
    this.group.add(mesh);
    this.ground = mesh;
  }

  private buildRings(): void {
    this.rings = new InstancedBatch(
      this.group,
      beaconRingGeometry(1, 0.13, this.quality === 'low' ? 40 : 84),
      this.ringMat,
      6,
      [
        { name: 'iColor', size: 3, fill: [1, 1, 1] },
        { name: 'iAux', size: 3, fill: [1, 0, 0] },
      ],
    );
    this.rings.setRenderOrder(6);
  }

  private buildGas(state: GameState): void {
    const gasIds: HexId[] = [];
    for (const id of this.idAt) {
      if (state.world.hexes[id]?.gas) gasIds.push(id);
    }
    if (gasIds.length === 0) return;

    // additive plume sprites
    this.plumes = new InstancedBatch(
      this.group,
      billboardQuadGeometry(1),
      this.plumeMat,
      gasIds.length,
      [
        { name: 'iColor', size: 3, fill: [1, 1, 1] },
        { name: 'iAux', size: 3, fill: [1, 1, 0] },
      ],
    );
    this.plumes.setRenderOrder(8);
    this.plumes.begin();
    for (const id of gasIds) {
      const idx = this.indexOf.get(id) ?? 0;
      hexWorld(id, V3);
      V3.y = this.topYAt[idx] + 0.85;
      M4.compose(V3, QUAT.identity(), SCALE.set(1, 1, 1));
      const i = this.plumes.add(M4);
      if (i < 0) break;
      this.plumes.set(i, 'iColor', 1, 1, 1);
      this.plumes.set(i, 'iAux', 1.35, 0.10, pseudoRandom(id));
    }
    this.plumes.end();

    // rising vent particles
    const perVent = this.quality === 'low' ? 4 : this.quality === 'medium' ? 6 : 9;
    const total = Math.min(2200, gasIds.length * perVent);
    const pos = new Float32Array(total * 3);
    const phase = new Float32Array(total);
    const speed = new Float32Array(total);
    const size = new Float32Array(total);
    const spread = new Float32Array(total * 2);
    let p = 0;
    for (const id of gasIds) {
      const idx = this.indexOf.get(id) ?? 0;
      hexWorld(id, V3);
      const baseY = this.topYAt[idx];
      for (let k = 0; k < perVent && p < total; k++, p++) {
        const a = Math.random() * Math.PI * 2;
        const rad = Math.sqrt(Math.random()) * PRISM_R * 0.6;
        pos[p * 3 + 0] = V3.x + Math.cos(a) * rad;
        pos[p * 3 + 1] = baseY + 0.02;
        pos[p * 3 + 2] = V3.z + Math.sin(a) * rad;
        phase[p] = Math.random();
        speed[p] = 0.7 + Math.random() * 0.8;
        size[p] = 1.5 + Math.random() * 2.4;
        spread[p * 2 + 0] = (Math.random() - 0.5) * 0.32;
        spread[p * 2 + 1] = (Math.random() - 0.5) * 0.32;
      }
    }
    const vgeo = new THREE.BufferGeometry();
    vgeo.setAttribute('position', new THREE.BufferAttribute(pos.subarray(0, p * 3), 3));
    vgeo.setAttribute('aPhase', new THREE.BufferAttribute(phase.subarray(0, p), 1));
    vgeo.setAttribute('aSpeed', new THREE.BufferAttribute(speed.subarray(0, p), 1));
    vgeo.setAttribute('aSize', new THREE.BufferAttribute(size.subarray(0, p), 1));
    vgeo.setAttribute('aSpread', new THREE.BufferAttribute(spread.subarray(0, p * 2), 2));
    vgeo.computeBoundingSphere();
    const points = new THREE.Points(vgeo, this.ventMat);
    points.name = 'gasVents';
    points.renderOrder = 7;
    points.frustumCulled = false;
    this.group.add(points);
    this.vents = points;
  }

  private buildObelisks(): void {
    for (const tier of [1, 2, 3] as const) {
      const batch = new InstancedBatch(this.group, obeliskGeometry(tier), this.obeliskMat, 48, [
        { name: 'iColor', size: 3, fill: [1, 1, 1] },
        { name: 'iAux', size: 3, fill: [1, 0, 0] },
      ]);
      batch.setRenderOrder(4);
      this.obelisks.push(batch);
    }
  }

  // ── per-state sync ────────────────────────────────────────────────────────

  sync(state: GameState, view: ViewState): void {
    if (!this.built) this.build(state);
    const mesh = this.mesh;
    if (!mesh) return;

    const now = state.now;
    const hexes = state.world.hexes;
    const sectors = state.world.sectors;
    const owner = this.ownerArr;
    const st = this.stateArr;

    for (let i = 0; i < this.idAt.length; i++) {
      const hex = hexes[this.idAt[i]];
      if (!hex) continue;

      // owner colour
      const col = hex.ownerId ? this.colorForOwner(state, hex.ownerId) : NEUTRAL_OWNER;
      const o = i * 3;
      if (owner[o] !== col.r || owner[o + 1] !== col.g || owner[o + 2] !== col.b) {
        owner[o] = col.r;
        owner[o + 1] = col.g;
        owner[o + 2] = col.b;
        this.ownerDirty = true;
      }

      // packed state
      const ownedFlag = hex.ownerId ? 1 : 0;
      const fort = hex.fortLevel;
      const cap = captureProgress(hex, now);
      const locked = lockedAmount(sectors[hex.sectorId]?.state);
      const s = i * 4;
      if (
        st[s] !== ownedFlag ||
        st[s + 1] !== fort ||
        Math.abs(st[s + 2] - cap) > 0.002 ||
        st[s + 3] !== locked
      ) {
        st[s] = ownedFlag;
        st[s + 1] = fort;
        st[s + 2] = cap;
        st[s + 3] = locked;
        this.stateDirty = true;
      }
    }

    if (this.ownerDirty) {
      const attr = mesh.geometry.getAttribute('iOwner');
      attr.needsUpdate = true;
      this.ownerDirty = false;
    }
    if (this.stateDirty) {
      const attr = mesh.geometry.getAttribute('iState');
      attr.needsUpdate = true;
      this.stateDirty = false;
    }

    this.selected = view.selectedHexId ?? null;
    this.syncObelisks(state);
  }

  private syncObelisks(state: GameState): void {
    // cheap signature so instance matrices are rebuilt only on real changes
    let sig = '';
    for (const id of this.idAt) {
      const hex = state.world.hexes[id];
      if (hex && hex.fortLevel > 0) sig += `${id}:${hex.fortLevel}|`;
    }
    if (sig === this.fortSig) return;
    this.fortSig = sig;

    const counts = [0, 0, 0];
    for (const id of this.idAt) {
      const hex = state.world.hexes[id];
      if (hex && hex.fortLevel > 0) counts[hex.fortLevel - 1]++;
    }
    for (let t = 0; t < 3; t++) this.obelisks[t].ensure(Math.max(1, counts[t]));
    for (const batch of this.obelisks) batch.begin();

    for (let i = 0; i < this.idAt.length; i++) {
      const id = this.idAt[i];
      const hex = state.world.hexes[id];
      if (!hex || hex.fortLevel === 0) continue;
      const batch = this.obelisks[hex.fortLevel - 1];
      hexWorld(id, V3);
      V3.y = this.topYAt[i];
      const s = HEX_R * 0.92;
      M4.compose(V3, QUAT.identity(), SCALE.set(s, s, s));
      const idx = batch.add(M4);
      if (idx < 0) continue;
      const col = hex.ownerId ? this.colorForOwner(state, hex.ownerId) : NEUTRAL_OWNER;
      batch.set(idx, 'iColor', col.r, col.g, col.b);
      batch.set(idx, 'iAux', 1, 0, hex.fortLevel / 3);
    }
    for (const batch of this.obelisks) batch.end();
  }

  // ── per-frame ─────────────────────────────────────────────────────────────

  update(dt: number, elapsed: number): void {
    this.pulse += dt;
    const rings = this.rings;
    if (!rings) return;
    rings.begin();

    if (this.hovered && this.hovered !== this.selected) {
      const idx = this.indexOf.get(this.hovered);
      if (idx !== undefined) {
        hexWorld(this.hovered, V3);
        V3.y = this.topYAt[idx] + 0.035;
        const s = HEX_R * 0.9;
        M4.compose(V3, QUAT.identity(), SCALE.set(s, 1, s));
        const i = rings.add(M4);
        if (i >= 0) {
          rings.set(i, 'iColor', 0.55, 0.92, 1.0);
          rings.set(i, 'iAux', 0.5, 0.3, 0);
        }
      }
    }

    if (this.selected) {
      const idx = this.indexOf.get(this.selected);
      if (idx !== undefined) {
        hexWorld(this.selected, V3);
        const baseY = this.topYAt[idx];
        const beat = 0.5 + 0.5 * Math.sin(elapsed * 3.1);

        // inner solid ring
        V3.y = baseY + 0.04;
        const s0 = HEX_R * 0.9;
        M4.compose(V3, QUAT.identity(), SCALE.set(s0, 1, s0));
        let i = rings.add(M4);
        if (i >= 0) {
          rings.set(i, 'iColor', 1, 1, 1);
          rings.set(i, 'iAux', 0.95, 0.1, 0);
        }

        // outward pulsing halo
        const grow = (elapsed * 0.9) % 1;
        V3.y = baseY + 0.05;
        const s1 = HEX_R * (0.9 + grow * 0.65);
        M4.compose(V3, QUAT.identity(), SCALE.set(s1, 1, s1));
        i = rings.add(M4);
        if (i >= 0) {
          rings.set(i, 'iColor', 0.4, 1, 0.92);
          rings.set(i, 'iAux', (1 - grow) * 0.7, 0.4, 0);
        }

        // slow counter-rotating bracket
        V3.y = baseY + 0.06;
        const s2 = HEX_R * (1.16 + beat * 0.03);
        QUAT.setFromAxisAngle(UP, -elapsed * 0.5);
        M4.compose(V3, QUAT, SCALE.set(s2, 1, s2));
        i = rings.add(M4);
        if (i >= 0) {
          rings.set(i, 'iColor', 1, 0.82, 0.36);
          rings.set(i, 'iAux', 0.28 + beat * 0.24, 0.7, 0);
        }
        QUAT.identity();
      }
    }

    rings.end();
  }

  // ── queries ───────────────────────────────────────────────────────────────

  /** Hex under the ray, resolved through the InstancedMesh instanceId. */
  hexAt(raycaster: THREE.Raycaster): HexId | null {
    const mesh = this.mesh;
    if (!mesh) return null;
    const hits = raycaster.intersectObject(mesh, false);
    for (const hit of hits) {
      if (hit.instanceId === undefined || hit.instanceId === null) continue;
      const id = this.idAt[hit.instanceId];
      if (id) return id;
    }
    return null;
  }

  setHover(hexId: HexId | null): void {
    this.hovered = hexId && this.indexOf.has(hexId) ? hexId : null;
  }

  has(hexId: HexId): boolean {
    return this.indexOf.has(hexId);
  }

  terrainOf(hexId: HexId): Terrain {
    const idx = this.indexOf.get(hexId);
    return idx === undefined ? 'plains' : this.terrainAt[idx];
  }

  /** Top-face world position of a hex (y already raised to the surface). */
  topOf(hexId: HexId, out: THREE.Vector3): THREE.Vector3 {
    hexWorld(hexId, out);
    const idx = this.indexOf.get(hexId);
    out.y = idx === undefined ? MAP_VIEW.hexHeight.plains : this.topYAt[idx];
    return out;
  }

  get instanceCount(): number {
    return this.idAt.length;
  }

  // ── colours ───────────────────────────────────────────────────────────────

  private colorForOwner(state: GameState, ownerId: PlayerId): THREE.Color {
    const player = state.players[ownerId];
    const guildId = player?.guildId;
    const key = guildId ? `g:${guildId}` : `p:${ownerId}`;
    const cached = this.ownerColors.get(key);
    if (cached) return cached;

    const col = new THREE.Color();
    if (guildId && state.guilds[guildId]) {
      col.setHex(state.guilds[guildId].color);
    } else if (player) {
      col.setHSL(((player.hue % 360) + 360) / 360, 0.72, 0.62);
    } else {
      col.copy(NEUTRAL_OWNER);
    }
    this.ownerColors.set(key, col);
    return col;
  }

  /** Guild colour lookup shared with the token / overlay layers. */
  static guildColor(state: GameState, guildId: string | undefined, out: THREE.Color): THREE.Color {
    if (guildId && state.guilds[guildId]) return out.setHex(state.guilds[guildId].color);
    return out.setHex(GUILD_COLORS[0]);
  }

  // ── teardown ──────────────────────────────────────────────────────────────

  private teardownWorld(): void {
    if (this.mesh) {
      this.group.remove(this.mesh);
      this.mesh.geometry.dispose();
      this.mesh.dispose();
      this.mesh = null;
    }
    if (this.ground) {
      this.group.remove(this.ground);
      this.ground.geometry.dispose();
      this.ground = null;
    }
    if (this.vents) {
      this.group.remove(this.vents);
      this.vents.geometry.dispose();
      this.vents = null;
    }
    this.rings?.dispose();
    this.rings = null;
    this.plumes?.dispose();
    this.plumes = null;
    for (const b of this.obelisks) b.dispose();
    this.obelisks.length = 0;
    this.indexOf.clear();
    this.idAt.length = 0;
    this.terrainAt.length = 0;
    this.topYAt.length = 0;
    this.fortSig = '';
    this.built = false;
  }

  dispose(): void {
    this.teardownWorld();
    this.hexMat.dispose();
    this.groundMat.dispose();
    this.ringMat.dispose();
    this.plumeMat.dispose();
    this.ventMat.dispose();
    this.obeliskMat.dispose();
    this.ownerColors.clear();
    this.group.removeFromParent();
    this.group.clear();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// helpers
// ─────────────────────────────────────────────────────────────────────────────

function captureProgress(hex: Hex, now: number): number {
  const cap = hex.capture;
  if (!cap) return 0;
  const span = cap.completesAt - cap.startedAt;
  if (span <= 0) return 1;
  return Math.min(1, Math.max(0, (now - cap.startedAt) / span));
}

function lockedAmount(state: string | undefined): number {
  switch (state) {
    case 'locked':
      return 1;
    case 'unlocking':
      return 0.55;
    case 'closing':
      return 0.2;
    default:
      return 0;
  }
}

/** Stable 0..1 hash for a hex id — keeps per-hex variation identical across runs. */
function pseudoRandom(key: string): number {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 100000) / 100000;
}
