/**
 * TERRA BELLUM — Global Map scene (GDD §12.2).
 *
 * Wires the whole strategic view together:
 *   Stage (renderer + console composite)
 *     └ scene
 *         ├ SpaceBackdrop   nebula, stars, dust
 *         ├ HexField        one instanced hex world + ground + forts + vents
 *         ├ ArmyTokens      chevrons, shadows, badges, trails, paths, drones
 *         ├ MapOverlays     pings, marks, objectives, borders, curtains, intel
 *         └ lighting rig    cool key + warm rim + hemisphere + sun flare
 *
 * Draw-call budget (GDD §13.8, < 100): ~30 with every layer live.
 */
import * as THREE from 'three';
import type { GameState, HexId } from '../../game/types';
import type { ViewState } from '../../game/store';
import { MAP_VIEW, PALETTE } from '../../config';
import { Stage } from '../core/stage';
import { SpaceBackdrop } from '../core/space';
import { MAP_LIGHT, makeGlowSpriteMaterial, type FxMaterial } from '../core/materials';
import { InstancedBatch, billboardQuadGeometry } from '../core/geometry';
import { HexField } from './hexField';
import { ArmyTokens } from './tokens';
import { MapOverlays } from './overlays';
import { MapControls } from './controls';

const HEX_R = MAP_VIEW.hexRadius;

const V = new THREE.Vector3();
const V2 = new THREE.Vector3();
const FLARE_POS = new THREE.Vector3();
const M4 = new THREE.Matrix4();
const QUAT = new THREE.Quaternion();
const SCALE = new THREE.Vector3(1, 1, 1);
const NDC = new THREE.Vector2();
const COL = new THREE.Color();

/** Sun flare: the core plus two lens ghosts riding back toward screen centre. */
const FLARE_LAYOUT: { t: number; size: number; alpha: number; tint: number }[] = [
  { t: 0, size: 11, alpha: 0.2, tint: 0xfff0d0 },
  { t: 0.36, size: 4.5, alpha: 0.03, tint: 0x9fd8ff },
  { t: 0.64, size: 7, alpha: 0.022, tint: 0x6fe6d0 },
];

export class MapScene {
  readonly stage: Stage;
  readonly scene: THREE.Scene;
  readonly camera: THREE.PerspectiveCamera;
  readonly controls: MapControls;
  readonly hexField: HexField;
  readonly tokens: ArmyTokens;
  readonly overlays: MapOverlays;
  readonly backdrop: SpaceBackdrop;

  private readonly keyLight: THREE.DirectionalLight;
  private readonly rimLight: THREE.DirectionalLight;
  private readonly hemiLight: THREE.HemisphereLight;
  private readonly flareMat: FxMaterial;
  private readonly flare: InstancedBatch;
  private readonly flareGroup = new THREE.Group();

  private tapCb: ((hexId: HexId) => void) | null = null;
  private longPressCb: ((hexId: HexId) => void) | null = null;
  private emptyTapCb: (() => void) | null = null;

  private readonly raycaster = new THREE.Raycaster();
  private lastFocusNonce = -1;
  private hasState = false;
  private elapsed = 0;
  private disposed = false;

  constructor(container: HTMLElement) {
    this.stage = new Stage(container);
    const quality = this.stage.quality;

    this.scene = new THREE.Scene();
    this.scene.name = 'mapScene';

    const cam = MAP_VIEW.camera;
    this.camera = new THREE.PerspectiveCamera(cam.fov, 1, cam.near, cam.far);
    this.camera.position.set(0, cam.startZoom * 0.8, cam.startZoom * 0.6);
    this.scene.add(this.camera);

    // ── lighting rig ───────────────────────────────────────────────────────
    this.keyLight = new THREE.DirectionalLight(MAP_LIGHT.keyColor, MAP_LIGHT.keyIntensity);
    this.keyLight.position.copy(MAP_LIGHT.keyDir).multiplyScalar(60);
    this.keyLight.castShadow = false;
    this.scene.add(this.keyLight);
    this.scene.add(this.keyLight.target);

    this.rimLight = new THREE.DirectionalLight(MAP_LIGHT.rimColor, MAP_LIGHT.rimIntensity);
    this.rimLight.position.copy(MAP_LIGHT.rimDir).multiplyScalar(60);
    this.scene.add(this.rimLight);
    this.scene.add(this.rimLight.target);

    this.hemiLight = new THREE.HemisphereLight(
      MAP_LIGHT.hemiSky,
      MAP_LIGHT.hemiGround,
      MAP_LIGHT.hemiIntensity,
    );
    this.scene.add(this.hemiLight);

    // ── layers ─────────────────────────────────────────────────────────────
    this.backdrop = new SpaceBackdrop(this.scene, {
      quality,
      pixelRatio: this.stage.profile.maxPixelRatio,
      dustSpan: 74,
    });

    this.hexField = new HexField(quality, this.stage.profile.maxPixelRatio);
    this.scene.add(this.hexField.group);

    this.tokens = new ArmyTokens(quality);
    this.scene.add(this.tokens.group);

    this.overlays = new MapOverlays(quality, this.stage.profile.devicePixelRatio);
    this.scene.add(this.overlays.group);

    // ── animated sun flare ─────────────────────────────────────────────────
    this.flareMat = makeGlowSpriteMaterial(0xffffff, 1.9);
    this.flareMat.uniforms.uCore.value = 1.6;
    this.scene.add(this.flareGroup);
    this.flareGroup.renderOrder = -400;
    this.flare = new InstancedBatch(
      this.flareGroup,
      billboardQuadGeometry(1),
      this.flareMat,
      FLARE_LAYOUT.length,
      [
        { name: 'iColor', size: 3, fill: [1, 1, 1] },
        { name: 'iAux', size: 3, fill: [1, 1, 0] },
      ],
    );
    this.flare.setRenderOrder(-400);
    this.flareMat.depthTest = false;

    // ── camera rig ─────────────────────────────────────────────────────────
    this.controls = new MapControls(this.camera, this.stage.canvas, {
      bounds: 90,
    });
    this.controls.onTap((x, y) => {
      const id = this.pick(x, y);
      if (id) this.tapCb?.(id);
      else this.emptyTapCb?.();
    });
    this.controls.onLongPress((x, y) => {
      const id = this.pick(x, y);
      if (id) this.longPressCb?.(id);
    });
    this.controls.onHover((x, y) => {
      if (x < 0) {
        this.hexField.setHover(null);
        return;
      }
      this.hexField.setHover(this.pick(x, y));
    });

    this.stage.setScene(this.scene, this.camera);
    this.stage.start(this.frame);
  }

  // ── frame ─────────────────────────────────────────────────────────────────

  private readonly frame = (dt: number, elapsed: number): void => {
    if (this.disposed) return;
    this.elapsed = elapsed;
    this.controls.update(dt);
    this.backdrop.update(dt, this.camera);
    this.hexField.update(dt, elapsed);
    this.tokens.update(dt);
    this.overlays.update(dt);
    this.updateFlare(elapsed);
  };

  private updateFlare(elapsed: number): void {
    // The "sun" sits along the key-light direction, effectively at infinity;
    // the lens ghosts ride back along the vector toward the view centre.
    V.copy(MAP_LIGHT.keyDir).multiplyScalar(MAP_LIGHT.sunDistance).add(this.camera.position);
    V2.copy(this.controls.target);
    const breathe = 0.9 + 0.1 * Math.sin(elapsed * 0.7) + 0.04 * Math.sin(elapsed * 3.3);

    this.flare.begin();
    for (let i = 0; i < FLARE_LAYOUT.length; i++) {
      const cfg = FLARE_LAYOUT[i];
      FLARE_POS.copy(V).lerp(V2, cfg.t);
      M4.compose(FLARE_POS, QUAT.identity(), SCALE.set(1, 1, 1));
      const idx = this.flare.add(M4);
      if (idx < 0) break;
      COL.setHex(cfg.tint);
      this.flare.set(idx, 'iColor', COL.r, COL.g, COL.b);
      this.flare.set(idx, 'iAux', cfg.size * breathe, cfg.alpha * (i === 0 ? breathe : 1), i * 0.31);
    }
    this.flare.end();
  }

  // ── state ─────────────────────────────────────────────────────────────────

  sync(state: GameState, view: ViewState): void {
    if (this.disposed) return;
    const first = !this.hasState;
    this.hasState = true;

    this.hexField.sync(state, view);
    this.tokens.sync(state, view);
    this.overlays.sync(state, view);

    this.controls.setBounds((state.world.radius + 4) * HEX_R * 1.75);
    this.controls.enabled = view.cinematic === undefined;

    // consume a focus request published through the view store
    if (view.focusHexId && view.focusNonce !== this.lastFocusNonce) {
      this.lastFocusNonce = view.focusNonce;
      this.focusHex(view.focusHexId, first);
    } else if (first) {
      const home = findHomeHex(state);
      if (home) this.focusHex(home, true);
    }
  }

  focusHex(hexId: HexId, instant = false): void {
    this.hexField.topOf(hexId, V);
    this.controls.focus(V, {
      instant,
      zoom: instant ? MAP_VIEW.camera.startZoom : undefined,
    });
  }

  /** One-shot shockwave — captures, pings, battle resolutions. */
  pulse(hexId: HexId, color: number): void {
    this.hexField.topOf(hexId, V);
    this.overlays.pulse(V, color, HEX_R * 3.4, 1.15);
  }

  /** Camera impulse (FX.shakeSmall / FX.shakeBig). */
  shake(amount: number, ms?: number): void {
    this.stage.shake(amount, ms);
  }

  onHexTap(cb: (hexId: HexId) => void): void {
    this.tapCb = cb;
  }

  onHexLongPress(cb: (hexId: HexId) => void): void {
    this.longPressCb = cb;
  }

  /** Fired when a tap misses every hex (deselect). */
  onEmptyTap(cb: () => void): void {
    this.emptyTapCb = cb;
  }

  /** Suppresses input during cinematics. */
  setInputEnabled(enabled: boolean): void {
    this.controls.enabled = enabled;
  }

  /** Pushes the console composite (0 = clean, 1 = normal, >1 = cinematic). */
  setPostStrength(x: number): void {
    this.stage.setPostStrength(x);
  }

  resize(): void {
    this.stage.resize();
  }

  get drawCalls(): number {
    return this.stage.drawCalls;
  }

  // ── picking ───────────────────────────────────────────────────────────────

  private pick(clientX: number, clientY: number): HexId | null {
    this.controls.toNdc(clientX, clientY, NDC);
    this.raycaster.setFromCamera(NDC, this.camera);
    return this.hexField.hexAt(this.raycaster);
  }

  /** Client-space point → the hex under it (used by drag-to-order previews). */
  hexAtScreen(clientX: number, clientY: number): HexId | null {
    return this.pick(clientX, clientY);
  }

  // ── teardown ──────────────────────────────────────────────────────────────

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.stage.stop();
    this.controls.dispose();
    this.flare.dispose();
    this.flareMat.dispose();
    this.scene.remove(this.flareGroup);
    this.overlays.dispose();
    this.tokens.dispose();
    this.hexField.dispose();
    this.backdrop.dispose();
    this.scene.remove(this.keyLight, this.keyLight.target);
    this.scene.remove(this.rimLight, this.rimLight.target);
    this.scene.remove(this.hemiLight);
    this.keyLight.dispose();
    this.rimLight.dispose();
    this.hemiLight.dispose();
    this.scene.clear();
    this.stage.dispose();
    this.tapCb = null;
    this.longPressCb = null;
    this.emptyTapCb = null;
  }
}

/** First hex owned by the local commander, else their first army's hex. */
function findHomeHex(state: GameState): HexId | undefined {
  for (const army of Object.values(state.armies)) {
    if (army.ownerId === state.meId) return army.hexId;
  }
  for (const id of Object.keys(state.world.hexes)) {
    if (state.world.hexes[id].ownerId === state.meId) return id;
  }
  for (const sector of Object.values(state.world.sectors)) {
    if (sector.state === 'active' && sector.hexIds.length > 0) return sector.hexIds[0];
  }
  return undefined;
}
