/**
 * Last-seen intel (GDD §5.1) — plus the small shared vocabulary every other
 * map panel needs (panel context, simulated clock, faction/vision helpers).
 *
 * This is the leaf of the `ui/map` graph: nothing here imports the other map
 * panels, so `buildPanel`, `armyPanel` and `hexSheet` can all pull from it.
 *
 * Drone relays are snapshotted with a timestamp and PERSIST after the mote has
 * moved on or died. The older the stamp, the louder the screen says so.
 */
import type { IBackend } from '../../backend/IBackend';
import { DRONES, ECONOMY, FORTS, TERRAIN_META } from '../../config';
import { UNITS } from '../../config/units';
import type {
  FortLevel,
  GameState,
  HexId,
  IntelSnapshot,
  PlayerId,
  Terrain,
  UnitType,
} from '../../game/types';
import { hexDistanceId, neighborIds } from '../../game/hex';
import { badge, sectionHeader, statRow, toast, unitSilhouette } from '../components';
import { cssHex, el, fmtAgo, svg as svgEl } from '../dom';
import type { Result } from '../../game/types';

// ─────────────────────────────────────────────────────────────────────────────
// Shared panel plumbing
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Everything a hex-sheet sub-panel is allowed to touch.
 *
 * Panels render once per structural change. Anything that has to stay live
 * between renders (affordability, meters) registers through `onSync`; anything
 * that has to be torn down (countdown rAF entries) registers through
 * `onDispose`.
 */
export interface PanelCtx {
  readonly backend: IBackend;
  /** Estimated authoritative clock, extrapolated between backend pushes. */
  now(): number;
  /** Force a full re-render of the owning sheet. */
  refresh(): void;
  /** Register a cheap per-push updater. */
  onSync(fn: (state: GameState) => void): void;
  /** Register a teardown callback, run before the next full render. */
  onDispose(fn: () => void): void;
}

/**
 * Estimator for the authoritative clock. `state.now` can run far ahead of wall
 * time (the offline sandbox compresses a season into a session), so countdowns
 * must tick on the *measured* rate, not on `Date.now()`.
 */
export class SimClock {
  private simAt = Date.now();
  private wallAt = Date.now();
  private rate = 1;

  sync(now: number): void {
    const wall = Date.now();
    const dWall = wall - this.wallAt;
    const dSim = now - this.simAt;
    if (dWall > 250 && dSim > 0) {
      const measured = dSim / dWall;
      if (measured > 0.05 && measured < 5000) this.rate = this.rate * 0.7 + measured * 0.3;
    }
    this.simAt = now;
    this.wallAt = wall;
  }

  now(): number {
    return this.simAt + (Date.now() - this.wallAt) * this.rate;
  }
}

/**
 * Fire a backend order and surface the outcome. Every `Result` in the UI goes
 * through here so a refusal is never swallowed.
 */
export async function commit(
  work: Promise<Result<unknown>>,
  okTitle: string,
  okBody?: string,
): Promise<boolean> {
  const res = await work;
  if (!res.ok) {
    toast({ title: 'ORDER REFUSED', body: res.error, kind: 'bad' });
    return false;
  }
  toast({ title: okTitle, body: okBody, kind: 'ok' });
  return true;
}

// ─────────────────────────────────────────────────────────────────────────────
// Faction / vision helpers
// ─────────────────────────────────────────────────────────────────────────────

/** A guildless commander is his own faction (mirrors world/movement.factionOf). */
export function factionKey(state: GameState, playerId: PlayerId): string {
  return state.players[playerId]?.guildId ?? playerId;
}

export function myFaction(state: GameState): string {
  return factionKey(state, state.meId);
}

/** The intel ledger of the local commander's faction. */
export function intelFor(state: GameState, hexId: HexId): IntelSnapshot | undefined {
  return state.intel[myFaction(state)]?.[hexId];
}

/**
 * Does the local faction have EYES on this hex right now?
 * Ground we hold, ground a friendly column stands on or beside, and anything
 * inside a live mote's relay radius.
 */
export function observesHex(state: GameState, hexId: HexId): boolean {
  const hex = state.world.hexes[hexId];
  if (!hex) return false;
  const mine = myFaction(state);
  if (hex.ownerId && factionKey(state, hex.ownerId) === mine) return true;

  const ring = new Set<HexId>([hexId, ...neighborIds(hexId)]);
  for (const army of Object.values(state.armies)) {
    if (army.units.length === 0) continue;
    if (factionKey(state, army.ownerId) !== mine) continue;
    if (ring.has(army.hexId)) return true;
  }
  for (const drone of Object.values(state.drones)) {
    if (!drone.alive) continue;
    if (factionKey(state, drone.ownerId) !== mine) continue;
    if (hexDistanceId(drone.hexId, hexId) <= DRONES.intelRadius) return true;
  }
  return false;
}

