export function fortLabel(level: FortLevel): string {
  return level === 0 ? 'OPEN GROUND' : FORTS[level].label;
}

/** `L2 BASTION` / `UNFORTIFIED` */
export function fortTag(level: FortLevel): string {
  return level === 0 ? 'UNFORTIFIED' : `L${level} ${FORTS[level].label}`;
}

/** Compact silhouette + count strip for an army composition. */
export function compositionStrip(
  composition: Partial<Record<UnitType, number>>,
  opts: { muted?: boolean } = {},
): HTMLElement {
  const row = el('div', { class: opts.muted ? 'comp comp--muted' : 'comp' });
  const entries = (Object.entries(composition) as [UnitType, number][])
    .filter(([, n]) => n > 0)
    .sort((a, b) => b[1] - a[1]);
  if (entries.length === 0) {
    row.appendChild(el('span', { class: 'comp__none', text: 'NO FORCES OBSERVED' }));
    return row;
  }
  for (const [type, n] of entries) {
    const chip = el('span', {
      class: 'comp__chip',
      style: `--accent:${UNIT_TINT[type]}`,
      aria: { label: `${n} ${UNITS[type].name}` },
    });
    chip.appendChild(svgEl(unitSilhouette(type), 'comp__art'));
    chip.appendChild(el('b', { class: 'mono', text: `×${n}` }));
    row.appendChild(chip);
  }
  return row;
}

const UNIT_TINT: Record<UnitType, string> = {
  exo: 'var(--cyan)',
  walker: 'var(--teal)',
  pallet: 'var(--amber)',
  flyer: 'var(--violet)',
  heavy_pallet: 'var(--gold)',
  elite_flyer: 'var(--magenta)',
  drone: 'var(--lime)',
};

// ─────────────────────────────────────────────────────────────────────────────
// Staleness
// ─────────────────────────────────────────────────────────────────────────────

export type Staleness = 'fresh' | 'aging' | 'stale' | 'cold';

const TICK = ECONOMY.tickMs;

/** Age bands are expressed in economy ticks so they scale with the config. */
export function intelStaleness(ageMs: number): Staleness {
  if (ageMs < TICK * 0.25) return 'fresh';
  if (ageMs < TICK) return 'aging';
  if (ageMs < TICK * 4) return 'stale';
  return 'cold';
}

const STALE_META: Record<Staleness, { label: string; note: string; kind: 'ok' | 'gold' | 'hot' | 'bad' }> = {
  fresh: {
    label: 'CURRENT',
    note: 'Relay is recent. Treat as accurate.',
    kind: 'ok',
  },
  aging: {
    label: 'AGEING',
    note: 'A production cycle old. Garrisons may have moved.',
    kind: 'gold',
  },
  stale: {
    label: 'STALE',
    note: 'Several cycles old. Assume the picture has changed.',
    kind: 'hot',
  },
  cold: {
    label: 'COLD',
    note: 'Historical only. Do not plan an assault on this.',
    kind: 'bad',
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// The panel
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The "last seen" view for a hex the local faction cannot currently observe.
 * Degrades visually as the snapshot ages: hairlines dim, a diagonal hatch
 * creeps in, and a STALE watermark stamps itself across the plate.
 */
export function intelPanel(state: GameState, hexId: HexId, ctx: PanelCtx): HTMLElement {
  const snap = intelFor(state, hexId);
  const root = el('div', { class: 'intel' });

  if (!snap) {
    root.classList.add('intel--void');
    root.appendChild(
      el(
        'div',
        { class: 'intel__head' },
        el('span', { class: 'intel__stamp', text: 'NO RECONNAISSANCE' }),
        badge('DARK', 'bad'),
      ),
    );
    root.appendChild(
      el('p', {
        class: 'intel__void',
        text:
          'This grid has never been relayed. Ownership, emplacements and garrison strength are unknown. ' +
          'Launch a recon mote from a held hex to open a picture.',
      }),
    );
    return root;
  }

  const age = Math.max(0, ctx.now() - snap.at);
  const level = intelStaleness(age);
  const meta = STALE_META[level];
  root.classList.add(`intel--${level}`);

  const head = el(
    'div',
    { class: 'intel__head' },
    el('span', { class: 'intel__stamp', text: 'LAST SEEN' }),
    el('span', { class: 'intel__age mono', text: fmtAgo(snap.at, ctx.now()) }),
    badge(meta.label, meta.kind),
  );
  root.appendChild(head);
  root.appendChild(el('div', { class: 'intel__watermark', text: meta.label, aria: { hidden: 'true' } }));

  const body = el('div', { class: 'intel__body' });
  body.appendChild(
    statRow('HOLDER', snap.ownerName ?? 'UNCLAIMED', {
      accent: snap.ownerId ? 'var(--crimson)' : 'var(--neutral)',
    }),
  );
  body.appendChild(statRow('BANNER', snap.guildTag ? `[${snap.guildTag}]` : '—'));
  body.appendChild(
    statRow('EMPLACEMENT', fortTag(snap.fortLevel), {
      accent: snap.fortLevel > 0 ? 'var(--amber)' : undefined,
    }),
  );

  if (snap.army) {
    body.appendChild(sectionHeader('OBSERVED COLUMN'));
    body.appendChild(
      statRow('COMMANDER', `${snap.army.ownerName} [${snap.army.guildTag}]`, {
        accent: 'var(--crimson)',
      }),
    );
    body.appendChild(statRow('STRENGTH', `${snap.army.unitCount} CHASSIS`));
    body.appendChild(compositionStrip(snap.army.composition, { muted: level !== 'fresh' }));
  } else {
    body.appendChild(sectionHeader('OBSERVED COLUMN'));
    body.appendChild(compositionStrip({}, { muted: true }));
  }

  body.appendChild(el('p', { class: 'intel__note', text: meta.note }));
  root.appendChild(body);
  return root;
}
